INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(95609, 3782, 2000, '<td valign="top">Very nice concept, well executed.</td>', 'Very nice concept, well executed.', '2002-07-29 13:51:00.000000', NULL, 1),
(95610, 3782, 2261, '<td valign="top">Your composition could have been alot better, but the detail and lighting is good.</td>', 'Your composition could have been alot better, but the detail and lighting is good.', '2002-07-29 14:15:00.000000', NULL, 1),
(95611, 3782, 2700, '<td valign="top">its sad, great shot 10</td>', 'its sad, great shot 10', '2002-07-30 02:35:00.000000', NULL, 1),
(95612, 3782, 2798, '<td valign="top">Not sure about the crop on this and the lighting is a little flat. Good use of irony but not as brash as "Foreign Flag" - also submitted this week. I think maybe we needed to see more of the garment.</td>', 'Not sure about the crop on this and the lighting is a little flat. Good use of irony but not as brash as "Foreign Flag" - also submitted this week. I think maybe we needed to see more of the garment.', '2002-07-30 08:51:00.000000', NULL, 1),
(95613, 3782, 811, '<td valign="top">Interesting and funny idea.  I think framing it differently, instead of straight on, would make it more interesting. karmat</td>', 'Interesting and funny idea.  I think framing it differently, instead of straight on, would make it more interesting. karmat', '2002-07-30 17:39:00.000000', NULL, 1),
(95614, 3782, 210, '<td valign="top">A bit of sharpening would have helped tremendously.</td>', 'A bit of sharpening would have helped tremendously.', '2002-07-30 19:32:00.000000', NULL, 1),
(95615, 3782, 121, '<td valign="top">Nice observation, I hope you didn''t pat too much for it they cost beans to make over there.</td>', 'Nice observation, I hope you didn''t pat too much for it they cost beans to make over there.', '2002-07-31 17:28:00.000000', NULL, 1),
(95616, 3782, 1280, '<td valign="top">The label might be worth a few bucks down the line.  I wonder if the stamp was ever corrected and how many have this typo.   Good clear image of information written to the consumer.</td>', 'The label might be worth a few bucks down the line.  I wonder if the stamp was ever corrected and how many have this typo.   Good clear image of information written to the consumer.', '2002-07-31 21:54:00.000000', NULL, 1),
(95617, 3782, 280, '<td valign="top">Good photo but seems to lack a little bit of focus.</td>', 'Good photo but seems to lack a little bit of focus.', '2002-08-01 17:07:00.000000', NULL, 1),
(95618, 3782, 472, '<td valign="top">yes. everything has a brand, doesnt it?  what brand are you? what brand am I? ;) mag99</td>', 'yes. everything has a brand, doesnt it?  what brand are you? what brand am I? ;) mag99', '2002-08-01 23:40:00.000000', NULL, 1),
(95619, 3782, 1467, '<td valign="top">Too funny.</td>', 'Too funny.', '2002-08-02 19:05:00.000000', NULL, 1),
(95620, 3782, 737, '<td valign="top">Composition - ok<br/>Technical Aspects - ok<br/>Meets Challenge - yes<br/>Visual Impact / Originality - ok<br/></td>', 'Composition - okTechnical Aspects - okMeets Challenge - yesVisual Impact / Originality - ok', '2002-08-04 23:27:00.000000', NULL, 1),
(95621, 3788, 772, '<td valign="top">interesting photo, but it doesn''t say ''corporate world'' without the title... - jmsetzler</td>', 'interesting photo, but it doesn''t say ''corporate world'' without the title... - jmsetzler', '2002-07-29 02:16:00.000000', NULL, 1),
(95622, 3788, 1360, '<td valign="top">This image looks like it was zoomed too much.</td>', 'This image looks like it was zoomed too much.', '2002-07-29 05:04:00.000000', NULL, 1),
(95623, 3788, 2798, '<td valign="top">Some badly noticable jpg artifacts in there. Is this a VERY close-in crop?</td>', 'Some badly noticable jpg artifacts in there. Is this a VERY close-in crop?', '2002-07-29 09:05:00.000000', NULL, 1),
(95624, 3788, 1, '<td valign="top">Seems a bit saturated.  Needs more detail to be effective.</td>', 'Seems a bit saturated.  Needs more detail to be effective.', '2002-07-29 10:56:00.000000', NULL, 1),
(95625, 3788, 2000, '<td valign="top">Nice coin collection.</td>', 'Nice coin collection.', '2002-07-29 13:53:00.000000', NULL, 1),
(95626, 3788, 2481, '<td valign="top">got a little pixelated; the edges of the coins would have been sharper if it didn''t pixelate on you</td>', 'got a little pixelated; the edges of the coins would have been sharper if it didn''t pixelate on you', '2002-07-29 13:54:00.000000', NULL, 1),
(95627, 3788, 2752, '<td valign="top">I think maybe you oversharpened..good theme and design</td>', 'I think maybe you oversharpened..good theme and design', '2002-07-29 18:30:00.000000', NULL, 1),
(95628, 3788, 441, '<td valign="top">only 69k used here  so severe pixilation results</td>', 'only 69k used here  so severe pixilation results', '2002-07-29 18:53:00.000000', NULL, 1),
(95629, 3788, 2983, '<td valign="top">This is noticeably blown-up from a smaller cropping.  I otherwise like the composition and overall tone.  Was it not possible to re-shoot zommed in and macro?</td>', 'This is noticeably blown-up from a smaller cropping.  I otherwise like the composition and overall tone.  Was it not possible to re-shoot zommed in and macro?', '2002-07-29 19:35:00.000000', NULL, 1),
(95630, 3788, 1005, '<td valign="top">The money looks REALLY old.  The whole shot seems a little pixelated.  My best guess is, you don''t have a Macro mode, so you took a picture of a much larger group of subject and cropped too far down.  If I''m wrong, I will gladly take it back.  Also, unless you were aiming for a "dark mood", the shot is too dark.  6 Swash</td>', 'The money looks REALLY old.  The whole shot seems a little pixelated.  My best guess is, you don''t have a Macro mode, so you took a picture of a much larger group of subject and cropped too far down.  If I''m wrong, I will gladly take it back.  Also, unless you were aiming for a "dark mood", the shot is too dark.  6 Swash', '2002-07-29 21:03:00.000000', NULL, 1),
(95631, 3788, 2158, '<td valign="top">Looks like you have cropped too tightly - the pixels are showing badly.</td>', 'Looks like you have cropped too tightly - the pixels are showing badly.', '2002-07-29 21:35:00.000000', NULL, 1),
(95632, 3788, 811, '<td valign="top">I like the idea, though the image is very pixelated.  it looks like it has been oversharpened, or cropped out of a much bigger image.</td>', 'I like the idea, though the image is very pixelated.  it looks like it has been oversharpened, or cropped out of a much bigger image.', '2002-07-30 00:22:00.000000', NULL, 1),
(95633, 3788, 2700, '<td valign="top">you might want to consider running a lower resoulin monitor. perhaps below 1600*1200, I see HUGE digitial artifacts at 1152*864</td>', 'you might want to consider running a lower resoulin monitor. perhaps below 1600*1200, I see HUGE digitial artifacts at 1152*864', '2002-07-30 02:32:00.000000', NULL, 1),
(95634, 3788, 2791, '<td valign="top">nice coins!!!! :)</td>', 'nice coins!!!! :)', '2002-07-30 06:58:00.000000', NULL, 1),
(95635, 3788, 1454, '<td valign="top">To me, the image quality is not very good.</td>', 'To me, the image quality is not very good.', '2002-07-30 11:39:00.000000', NULL, 1),
(95636, 3788, 2784, '<td valign="top">close up could''ve been a lot cleaner</td>', 'close up could''ve been a lot cleaner', '2002-07-30 16:54:00.000000', NULL, 1),
(95637, 3788, 210, '<td valign="top">Compression is horrible: Camera or Photoshop?</td>', 'Compression is horrible: Camera or Photoshop?', '2002-07-30 19:26:00.000000', NULL, 1),
(95638, 3788, 3014, '<td valign="top">Reminds me of my own coin collection...</td>', 'Reminds me of my own coin collection...', '2002-07-30 22:49:00.000000', NULL, 1),
(95639, 3788, 1169, '<td valign="top">compressed too much</td>', 'compressed too much', '2002-07-31 04:35:00.000000', NULL, 1),
(95640, 3788, 2146, '<td valign="top">wish I had these in my coin collection</td>', 'wish I had these in my coin collection', '2002-07-31 08:08:00.000000', NULL, 1),
(95641, 3788, 2858, '<td valign="top">Beautiful tones and colours. Pixels showing because of over-cropping? Also good for ''something old''.</td>', 'Beautiful tones and colours. Pixels showing because of over-cropping? Also good for ''something old''.', '2002-07-31 09:44:00.000000', NULL, 1),
(95642, 3788, 2815, '<td valign="top">Lke the photo, but there are some strange line in the photo, kinfd o</td>', 'Lke the photo, but there are some strange line in the photo, kinfd o', '2002-07-31 11:30:00.000000', NULL, 1),
(95643, 3788, 1280, '<td valign="top">The love of it IS the root of ALL evil.  Simple concept, well executed.  I like that the focal point leads to the lower left corner, that it''s facing down.  That echoes the concept, but I would like to see a little more of that coin covered up by the other coins.  To me it would just be a better composition. A little rearranging of the coins.  Of course I know it''s my personal perspective though.  Nice job.  "6"</td>', 'The love of it IS the root of ALL evil.  Simple concept, well executed.  I like that the focal point leads to the lower left corner, that it''s facing down.  That echoes the concept, but I would like to see a little more of that coin covered up by the other coins.  To me it would just be a better composition. A little rearranging of the coins.  Of course I know it''s my personal perspective though.  Nice job.  "6"', '2002-07-31 17:02:00.000000', NULL, 1),
(95644, 3788, 2251, '<td valign="top">To learn more about the detramental effects of capitalism and statism, go to www.infoshop.org<br/>-Ben</td>', 'To learn more about the detramental effects of capitalism and statism, go to www.infoshop.org-Ben', '2002-07-31 18:42:00.000000', NULL, 1),
(95645, 3788, 1944, '<td valign="top">I like the composition of your photo a lot, and the exposure is excellent, but it appears to be very low resolution, and also over compressed. Notice the pixelation on all the detail, or were you trying for this effect? On second thought, think I''ll give you the three extra points I took away for poor quality.</td>', 'I like the composition of your photo a lot, and the exposure is excellent, but it appears to be very low resolution, and also over compressed. Notice the pixelation on all the detail, or were you trying for this effect? On second thought, think I''ll give you the three extra points I took away for poor quality.', '2002-08-01 00:21:00.000000', NULL, 1),
(95646, 3788, 1882, '<td valign="top">not very clear.  Was that on purpuse?</td>', 'not very clear.  Was that on purpuse?', '2002-08-02 09:18:00.000000', NULL, 1),
(95647, 3788, 2923, '<td valign="top">I don''t get how a photo of a bunch of coins represents corporate evil.</td>', 'I don''t get how a photo of a bunch of coins represents corporate evil.', '2002-08-02 12:03:00.000000', NULL, 1),
(95648, 3788, 637, '<td valign="top">How does money imply corporate?  To me, money implies a quart of milk, a newspaper, bus fare.  The image could be nicer in any case.  I think you could''ve done more with a pile of change.  3 sjgleah</td>', 'How does money imply corporate?  To me, money implies a quart of milk, a newspaper, bus fare.  The image could be nicer in any case.  I think you could''ve done more with a pile of change.  3 sjgleah', '2002-08-04 03:46:00.000000', NULL, 1),
(95649, 3788, 2109, '<td valign="top">really grainy, low res</td>', 'really grainy, low res', '2002-08-04 17:19:00.000000', NULL, 1),
(95650, 3788, 2719, '<td valign="top">Poor compression.</td>', 'Poor compression.', '2002-08-04 18:41:00.000000', NULL, 1),
(95651, 3788, 509, '<td valign="top">Wow, this looks very compressed.  Was it intentional?  With the subjects chosen, it has a pretty cool effect.</td>', 'Wow, this looks very compressed.  Was it intentional?  With the subjects chosen, it has a pretty cool effect.', '2002-08-04 19:28:00.000000', NULL, 1),
(95652, 3788, 2223, '<td valign="top">Thanks to everyone who voted for me, and all the comments that helped me realize how  i could have improved the picture, but it was my first attempt.</td>', 'Thanks to everyone who voted for me, and all the comments that helped me realize how  i could have improved the picture, but it was my first attempt.', '2002-08-05 15:08:00.000000', NULL, 0),
(95653, 3790, 2907, '<td valign="top">Suds in basin... interesting idea...</td>', 'Suds in basin... interesting idea...', '2002-07-29 03:52:00.000000', NULL, 1),
(95654, 3790, 2000, '<td valign="top">Nice picture.  How does this relate to anything corporate???</td>', 'Nice picture.  How does this relate to anything corporate???', '2002-07-29 13:57:00.000000', NULL, 1),
(95655, 3790, 2798, '<td valign="top">Looks like out of focus bubblebath. What has this to do with the ozone layer or the corporate world? Also badly over exposed in the middle.</td>', 'Looks like out of focus bubblebath. What has this to do with the ozone layer or the corporate world? Also badly over exposed in the middle.', '2002-07-30 09:29:00.000000', NULL, 1),
(95656, 3790, 3002, '<td valign="top">What is this REALLY a photo of?  It looks like soapsuds or a melted plastic thingy of some kind where the light bulb is burning through?  Pretty colors though!</td>', 'What is this REALLY a photo of?  It looks like soapsuds or a melted plastic thingy of some kind where the light bulb is burning through?  Pretty colors though!', '2002-07-30 12:46:00.000000', NULL, 1),
(95657, 3790, 737, '<td valign="top">Composition - ok, but this is not what an ozone layer looks like<br/>Technical Aspects - middle is blown out trying to represent damage<br/>Meets Challenge - not really. Title tries to carry it.<br/>Visual Impact / Originality - ok<br/></td>', 'Composition - ok, but this is not what an ozone layer looks likeTechnical Aspects - middle is blown out trying to represent damageMeets Challenge - not really. Title tries to carry it.Visual Impact / Originality - ok', '2002-07-31 01:00:00.000000', NULL, 1),
(95658, 3790, 2146, '<td valign="top">to bright</td>', 'to bright', '2002-07-31 07:50:00.000000', NULL, 1),
(95659, 3790, 2261, '<td valign="top">Seems to much light and not enough detail, but I don''t know how you did this so it may be a fantastic result!</td>', 'Seems to much light and not enough detail, but I don''t know how you did this so it may be a fantastic result!', '2002-07-31 13:44:00.000000', NULL, 1),
(95660, 3790, 2361, '<td valign="top">The link to the challenge is cerebral at best, and quite impossible for the viewer to grasp</td>', 'The link to the challenge is cerebral at best, and quite impossible for the viewer to grasp', '2002-07-31 19:31:00.000000', NULL, 1),
(95661, 3790, 1280, '<td valign="top">Ohhhh I hate to think of it!  This has impact, and it conveys a frightening truth. I''m guessing at how you achieved this bright image, and it''s giving me ideas.  I think that is pretty powerful!  If you can inspire another artist or anyone, that is a quality of a good picture.<br/>The thing I don''t like is the perimeter of the image.  Maybe I would have composed or cropped it differently. Strictly personal taste though.  I''d like some of the bubbles to be clearer,  there seems to be a haze over all.  Still one of my favorites.</td>', 'Ohhhh I hate to think of it!  This has impact, and it conveys a frightening truth. I''m guessing at how you achieved this bright image, and it''s giving me ideas.  I think that is pretty powerful!  If you can inspire another artist or anyone, that is a quality of a good picture.The thing I don''t like is the perimeter of the image.  Maybe I would have composed or cropped it differently. Strictly personal taste though.  I''d like some of the bubbles to be clearer,  there seems to be a haze over all.  Still one of my favorites.', '2002-07-31 22:05:00.000000', NULL, 1),
(95662, 3790, 1, '<td valign="top">Corporate world?</td>', 'Corporate world?', '2002-08-01 10:00:00.000000', NULL, 1),
(95663, 3790, 472, '<td valign="top">awesome statement. . i think the glare and overexposure hurts the execution for me , though . mag99.</td>', 'awesome statement. . i think the glare and overexposure hurts the execution for me , though . mag99.', '2002-08-01 23:54:00.000000', NULL, 1),
(95664, 3790, 772, '<td valign="top">where are my sunglasses :))  nice abstract... - jmsetzler</td>', 'where are my sunglasses :))  nice abstract... - jmsetzler', '2002-08-02 10:57:00.000000', NULL, 1),
(95665, 3790, 2456, '<td valign="top">cool picture. Hasn''t to do too much with the subject of corporate world for me though. Sorry, Daniella</td>', 'cool picture. Hasn''t to do too much with the subject of corporate world for me though. Sorry, Daniella', '2002-08-02 13:05:00.000000', NULL, 1),
(95666, 3791, 1054, '<td valign="top">Sorry but this is not very visually interesting.  It does fit the theme, though.</td>', 'Sorry but this is not very visually interesting.  It does fit the theme, though.', '2002-07-29 03:02:00.000000', NULL, 1),
(95667, 3791, 210, '<td valign="top">Down the drain?  The economy or aesthetics?  =)</td>', 'Down the drain?  The economy or aesthetics?  =)', '2002-07-29 04:20:00.000000', NULL, 1),
(95668, 3791, 2295, '<td valign="top">Interesting.  Focus is a bit soft, lighing is good.</td>', 'Interesting.  Focus is a bit soft, lighing is good.', '2002-07-29 09:42:00.000000', NULL, 1),
(95669, 3791, 789, '<td valign="top">Thanks for wasting my time.</td>', 'Thanks for wasting my time.', '2002-07-29 10:24:00.000000', NULL, 1),
(95670, 3791, 1, '<td valign="top">Nice idea, though you need a lot more light so the water doesn''t blur.  Without the title, I''d be wondering what I was looking at.</td>', 'Nice idea, though you need a lot more light so the water doesn''t blur.  Without the title, I''d be wondering what I was looking at.', '2002-07-29 10:35:00.000000', NULL, 1),
(95671, 3791, 2923, '<td valign="top">cliche!!!!</td>', 'cliche!!!!', '2002-07-29 16:34:00.000000', NULL, 1),
(95672, 3791, 1005, '<td valign="top">Two toilet shots this week.  It''s a stretch, but I''m going along with the idea.  Personally, I think the shot needs more to connect it to the corporate concept, maybe cr@p wrapped in $$ or a very red balance sheet, that sort of thing.  The toilet alone just isn''t enough and the title isn''t supposed to "save" you.  Since I already gave the other toilet a 4, but it was tweeked wierdly and your''s isn''t, I will give you one more point, so 5 it is.  Swash</td>', 'Two toilet shots this week.  It''s a stretch, but I''m going along with the idea.  Personally, I think the shot needs more to connect it to the corporate concept, maybe cr@p wrapped in $$ or a very red balance sheet, that sort of thing.  The toilet alone just isn''t enough and the title isn''t supposed to "save" you.  Since I already gave the other toilet a 4, but it was tweeked wierdly and your''s isn''t, I will give you one more point, so 5 it is.  Swash', '2002-07-29 19:53:00.000000', NULL, 1),
(95673, 3791, 1569, '<td valign="top">This would have been really great if it were more in focus. It looks like the moving water fooled the auto focus and couldn''t fix on any one part.</td>', 'This would have been really great if it were more in focus. It looks like the moving water fooled the auto focus and couldn''t fix on any one part.', '2002-07-29 21:39:00.000000', NULL, 1),
(95674, 3791, 2352, '<td valign="top">I get the idea, but the shot just doesn`t work for me...</td>', 'I get the idea, but the shot just doesn`t work for me...', '2002-07-29 22:10:00.000000', NULL, 1),
(95675, 3791, 811, '<td valign="top">seems to be a very soft focus/ or out of focus.  maybe if the water had one of those little blue tablets, or there was a little sailboat going round and round.</td>', 'seems to be a very soft focus/ or out of focus.  maybe if the water had one of those little blue tablets, or there was a little sailboat going round and round.', '2002-07-30 00:25:00.000000', NULL, 1),
(95676, 3791, 2798, '<td valign="top">We''ve seen quite a few examples of this idea this week and this is, sadly, not the best. Focus is badly off and there''s a general lack of colour and depth. A stronger light off to one side would have put highlights on the water that would have more clearly defined things. Also stepping further away from the subject would have shown us that this is, in fact, a toilet.</td>', 'We''ve seen quite a few examples of this idea this week and this is, sadly, not the best. Focus is badly off and there''s a general lack of colour and depth. A stronger light off to one side would have put highlights on the water that would have more clearly defined things. Also stepping further away from the subject would have shown us that this is, in fact, a toilet.', '2002-07-30 11:20:00.000000', NULL, 1),
(95677, 3791, 436, '<td valign="top">It''s not crisp enough and it''s actually rather bland.  Interesting that it''s one ot 2 toilet pictures this week.  What if you scanned in some money and printed it out on the color printer and flushed that?  it would give the viewer something to focus on and liven up the photo.</td>', 'It''s not crisp enough and it''s actually rather bland.  Interesting that it''s one ot 2 toilet pictures this week.  What if you scanned in some money and printed it out on the color printer and flushed that?  it would give the viewer something to focus on and liven up the photo.', '2002-07-30 14:18:00.000000', NULL, 1),
(95678, 3791, 2983, '<td valign="top">Too fuzzy.  A better setup would''ve helped</td>', 'Too fuzzy.  A better setup would''ve helped', '2002-07-30 14:30:00.000000', NULL, 1),
(95679, 3791, 3014, '<td valign="top">Yet another toilet photo.</td>', 'Yet another toilet photo.', '2002-07-30 23:16:00.000000', NULL, 1),
(95680, 3791, 737, '<td valign="top">Composition - poor. What is "down the drain" ?<br/>Technical Aspects - ok<br/>Meets Challenge - not really<br/>Visual Impact / Originality - poor<br/></td>', 'Composition - poor. What is "down the drain" ?Technical Aspects - okMeets Challenge - not reallyVisual Impact / Originality - poor', '2002-07-31 00:57:00.000000', NULL, 1),
(95681, 3791, 2361, '<td valign="top">Sorry, but this is a terrible shot of a cliched image.</td>', 'Sorry, but this is a terrible shot of a cliched image.', '2002-07-31 19:26:00.000000', NULL, 1),
(95682, 3791, 1856, '<td valign="top">Interesting concept.  I would have liked more focus and maybe a glimpse of something corp related going down the drain.  That could be pretty hard on the plumbing though.  It''s also a little hard to figure out what this is without the title.</td>', 'Interesting concept.  I would have liked more focus and maybe a glimpse of something corp related going down the drain.  That could be pretty hard on the plumbing though.  It''s also a little hard to figure out what this is without the title.', '2002-07-31 20:16:00.000000', NULL, 1),
(95683, 3791, 772, '<td valign="top">I do understand your interpretation here... I wish you could have found a more visually appealing way to show the mood.  This particular image lacks contrast... - jmsetzler</td>', 'I do understand your interpretation here... I wish you could have found a more visually appealing way to show the mood.  This particular image lacks contrast... - jmsetzler', '2002-08-02 10:51:00.000000', NULL, 1),
(95684, 3791, 806, '<td valign="top">This is just a toilet - now if you pretended (since you don''t want to have to call a plumber) to be flushing something, say a stock portfolio or what-have-you, it may make better sense to the viewer.</td>', 'This is just a toilet - now if you pretended (since you don''t want to have to call a plumber) to be flushing something, say a stock portfolio or what-have-you, it may make better sense to the viewer.', '2002-08-04 00:39:00.000000', NULL, 1),
(95685, 3794, 210, '<td valign="top">I think the idea, no matter how cliche, is nice.  Something that bugged me was the color of the newspapers getting whiter nearer the bottom right corner.  So, it''s a mixture of proper organization and discoloration, which tends to leave a bit of a bad taste.</td>', 'I think the idea, no matter how cliche, is nice.  Something that bugged me was the color of the newspapers getting whiter nearer the bottom right corner.  So, it''s a mixture of proper organization and discoloration, which tends to leave a bit of a bad taste.', '2002-07-29 02:50:00.000000', NULL, 1),
(95686, 3794, 2798, '<td valign="top">Great composition and quality of photo.</td>', 'Great composition and quality of photo.', '2002-07-29 09:39:00.000000', NULL, 1),
(95687, 3794, 2553, '<td valign="top">The only thing missing are the keys to a Porsche! Good lighting. I think in the composition, that it would have been more interesting to shuffle the items around a bit tighter so that more of the headlines were only partially visible, leaving the imagination to fill in some of the blanks.</td>', 'The only thing missing are the keys to a Porsche! Good lighting. I think in the composition, that it would have been more interesting to shuffle the items around a bit tighter so that more of the headlines were only partially visible, leaving the imagination to fill in some of the blanks.', '2002-07-29 14:41:00.000000', NULL, 1),
(95688, 3794, 2337, '<td valign="top">Very well done.  If I was to nitpick one little thing, did you crop so close on the phone on purpose?  It feels kind of tight to me... But certainly this is VERY well done</td>', 'Very well done.  If I was to nitpick one little thing, did you crop so close on the phone on purpose?  It feels kind of tight to me... But certainly this is VERY well done', '2002-07-30 03:09:00.000000', NULL, 1),
(95689, 3794, 2928, '<td valign="top">Technically, a great picture - but I''m put off by the fact that it looks a bit thrown together.  I can''t fault exposure and lighting, put composition seems a bit haphazard.  I think I would have scored higher if the phone were a central feature  but hey, I''m no pro; good luck</td>', 'Technically, a great picture - but I''m put off by the fact that it looks a bit thrown together.  I can''t fault exposure and lighting, put composition seems a bit haphazard.  I think I would have scored higher if the phone were a central feature  but hey, I''m no pro; good luck', '2002-07-30 10:05:00.000000', NULL, 1),
(95690, 3794, 2983, '<td valign="top">Cell phone seems out of place here</td>', 'Cell phone seems out of place here', '2002-07-30 14:53:00.000000', NULL, 1),
