(95772, 3806, 2352, '<td valign="top">Nice clean shot with good subject matter for the challenge!  I like the angles and contrasts!  Very well done</td>', 'Nice clean shot with good subject matter for the challenge!  I like the angles and contrasts!  Very well done', '2002-07-29 22:17:00.000000', NULL, 1),
(95773, 3806, 2195, '<td valign="top">this has a dizzying effect..the compression of the background is immense...great shot I like it-8</td>', 'this has a dizzying effect..the compression of the background is immense...great shot I like it-8', '2002-07-30 00:06:00.000000', NULL, 1),
(95774, 3806, 2337, '<td valign="top">Can I have my breath back when your done with it? This shot took it away... Solid 10</td>', 'Can I have my breath back when your done with it? This shot took it away... Solid 10', '2002-07-30 00:16:00.000000', NULL, 1),
(95775, 3806, 2700, '<td valign="top">10!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!</td>', '10!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!', '2002-07-30 02:30:00.000000', NULL, 1),
(95776, 3806, 2798, '<td valign="top">I love this one - great concept and execution. I love contrasts and this one is very well done. Beautifully un-cluttered and simple. Exposure is bang on. Focus is good. I just cant quite decide if this is best left in B&amp;W or if some kind of colour contrast would help things. Perhaps have the steeple in colour and the rest B&amp;W? Outside the scope of this competition, though.</td>', 'I love this one - great concept and execution. I love contrasts and this one is very well done. Beautifully un-cluttered and simple. Exposure is bang on. Focus is good. I just cant quite decide if this is best left in B&W or if some kind of colour contrast would help things. Perhaps have the steeple in colour and the rest B&W? Outside the scope of this competition, though.', '2002-07-30 08:44:00.000000', NULL, 1),
(95777, 3806, 2923, '<td valign="top">i like this, but then again, i wouldn''t say the church is "heaven" when there are priests around :)</td>', 'i like this, but then again, i wouldn''t say the church is "heaven" when there are priests around :)', '2002-07-30 13:46:00.000000', NULL, 1),
