(95779, 3806, 210, '<td valign="top">Great juxtaposition!  7.</td>', 'Great juxtaposition!  7.', '2002-07-30 19:37:00.000000', NULL, 1),
(95780, 3806, 2109, '<td valign="top">I like the simplicity of this!  Were you able to try different angles to get the buildings and church on different lines?</td>', 'I like the simplicity of this!  Were you able to try different angles to get the buildings and church on different lines?', '2002-07-30 22:24:00.000000', NULL, 1),
(95781, 3806, 3014, '<td valign="top">Being an atheist, I have trouble deciphering which is which in this photo. (I could swear I''ve seen a similar shot somewhere before.)</td>', 'Being an atheist, I have trouble deciphering which is which in this photo. (I could swear I''ve seen a similar shot somewhere before.)', '2002-07-31 03:03:00.000000', NULL, 1),
