(95792, 3806, 2261, '<td valign="top">Excellent.</td>', 'Excellent.', '2002-08-03 12:29:00.000000', NULL, 1),
(95793, 3806, 811, '<td valign="top">I like the bw and the strong vertical lines of this.  The steeple really provides a contrast with that, in more ways than one. karmat</td>', 'I like the bw and the strong vertical lines of this.  The steeple really provides a contrast with that, in more ways than one. karmat', '2002-08-03 14:03:00.000000', NULL, 1),
(95794, 3806, 2323, '<td valign="top">I''m not sure that B&amp;W works well for this photo, but I do like the theme.</td>', 'I''m not sure that B&W works well for this photo, but I do like the theme.', '2002-08-04 21:43:00.000000', NULL, 1),
(95795, 3806, 2221, '<td valign="top">i love this photo. it''s simple but tells a lot. very effective.</td>', 'i love this photo. it''s simple but tells a lot. very effective.', '2002-08-04 22:26:00.000000', NULL, 1),
(95796, 3806, 1569, '<td valign="top">Congratulations on seccond place--great picture!!</td>', 'Congratulations on seccond place--great picture!!', '2002-08-05 09:51:00.000000', NULL, 0),
(95797, 3806, 2244, '<td valign="top">Very happy to see that the view from my office window could land me a 2nd place this week!!!  Actually, I have to walk a few cubicles away to get the right angle.  It was shot pretty much "at level" from the 22nd floor of tower 49 in Midtown Manhattan.  In terms of composition the choices are pretty much limited to using the 2 St-Patricks towers and 3 buildings in the background vs. 1/2 like I did here.  Shot with a 190 mm zoom (300mm effective) zoom at 5.6 f-stop with 350th speed to avoid blur (typically even better at 500th) - ISO 200.  Black and white was much more effective as it enhances the contrast of the church.  Thanks for all the comments and feedback + votes!!</td>', 'Very happy to see that the view from my office window could land me a 2nd place this week!!!  Actually, I have to walk a few cubicles away to get the right angle.  It was shot pretty much "at level" from the 22nd floor of tower 49 in Midtown Manhattan.  In terms of composition the choices are pretty much limited to using the 2 St-Patricks towers and 3 buildings in the background vs. 1/2 like I did here.  Shot with a 190 mm zoom (300mm effective) zoom at 5.6 f-stop with 350th speed to avoid blur (typically even better at 500th) - ISO 200.  Black and white was much more effective as it enhances the contrast of the church.  Thanks for all the comments and feedback + votes!!', '2002-08-11 15:45:00.000000', NULL, 0),
(95798, 3807, 2586, '<td valign="top">This could just as well convey inner city rehabilitation! The foreground (also the left) is just way too dark. The middle with the sunlit walls and all the action is nice though.</td>', 'This could just as well convey inner city rehabilitation! The foreground (also the left) is just way too dark. The middle with the sunlit walls and all the action is nice though.', '2002-07-29 04:07:00.000000', NULL, 1),
(95799, 3807, 2223, '<td valign="top">yes it will...</td>', 'yes it will...', '2002-07-29 13:16:00.000000', NULL, 1),
(95800, 3807, 2481, '<td valign="top">dark foreground effective;  background a little blown out</td>', 'dark foreground effective;  background a little blown out', '2002-07-29 13:57:00.000000', NULL, 1),
(95801, 3807, 2752, '<td valign="top">good depth and contrast</td>', 'good depth and contrast', '2002-07-29 18:14:00.000000', NULL, 1),
(95802, 3807, 2858, '<td valign="top">This pic could possibly have been metered better by choosing a spot half way down on the right, allowing more details of the interesting foreground to show through. Also, a bit more cropping?</td>', 'This pic could possibly have been metered better by choosing a spot half way down on the right, allowing more details of the interesting foreground to show through. Also, a bit more cropping?', '2002-07-30 08:28:00.000000', NULL, 1),
(95803, 3807, 2798, '<td valign="top">Foreground way too dark. Background overexposed. Good concept but perhaps a fill-in flash and tweak to exposure would have helped.</td>', 'Foreground way too dark. Background overexposed. Good concept but perhaps a fill-in flash and tweak to exposure would have helped.', '2002-07-30 09:17:00.000000', NULL, 1),
(95804, 3807, 2983, '<td valign="top">Don''t be afraid to use a flash outdoors to fill in harsh shadows</td>', 'Don''t be afraid to use a flash outdoors to fill in harsh shadows', '2002-07-30 15:57:00.000000', NULL, 1),
(95805, 3807, 2123, '<td valign="top">The sunlight was working against you here. :-)  The foreground is dark and the background is a bit washed out.</td>', 'The sunlight was working against you here. :-)  The foreground is dark and the background is a bit washed out.', '2002-07-30 17:32:00.000000', NULL, 1),
(95806, 3807, 835, '<td valign="top">I don''t care for the lighting &amp; I''m not certain what you are trying to portray</td>', 'I don''t care for the lighting & I''m not certain what you are trying to portray', '2002-07-30 18:30:00.000000', NULL, 1),
(95807, 3807, 3014, '<td valign="top">The photo says a lot on its own, but I think a more ironic title would be better.</td>', 'The photo says a lot on its own, but I think a more ironic title would be better.', '2002-07-31 03:22:00.000000', NULL, 1),
(95808, 3807, 2370, '<td valign="top">the bottom part of the photo is underexposed, perhaps flash would be useful here?</td>', 'the bottom part of the photo is underexposed, perhaps flash would be useful here?', '2002-08-01 22:11:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(95809, 3807, 637, '<td valign="top">I don''t know what i''m looking at or what makes it corporate... 3 sjgleah</td>', 'I don''t know what i''m looking at or what makes it corporate... 3 sjgleah', '2002-08-04 03:49:00.000000', NULL, 1),
(95810, 3808, 772, '<td valign="top">interesting photo, but the post processing isn''t working for me... it is almost over the limit of still looking like a photograph... - jmsetzler</td>', 'interesting photo, but the post processing isn''t working for me... it is almost over the limit of still looking like a photograph... - jmsetzler', '2002-07-29 02:06:00.000000', NULL, 1),
(95811, 3808, 1793, '<td valign="top">you have done too much editing with this.</td>', 'you have done too much editing with this.', '2002-07-29 02:21:00.000000', NULL, 1),
(95812, 3808, 2311, '<td valign="top">outstanding colors...could not have done better...</td>', 'outstanding colors...could not have done better...', '2002-07-29 03:16:00.000000', NULL, 1),
(95813, 3808, 2370, '<td valign="top">nice use of inversion to create a surreal, pointillistic effect.</td>', 'nice use of inversion to create a surreal, pointillistic effect.', '2002-07-29 04:18:00.000000', NULL, 1),
(95814, 3808, 2798, '<td valign="top">Doesnt this break the rules about filters? Other than that - good shot but it looks kinda like it''s leaning to the right.</td>', 'Doesnt this break the rules about filters? Other than that - good shot but it looks kinda like it''s leaning to the right.', '2002-07-29 09:19:00.000000', NULL, 1),
(95815, 3808, 671, '<td valign="top">I like the color effects and graniness.  They work well with this picture.</td>', 'I like the color effects and graniness.  They work well with this picture.', '2002-07-29 10:28:00.000000', NULL, 1),
(95816, 3808, 2752, '<td valign="top">very good use of color to set the mood</td>', 'very good use of color to set the mood', '2002-07-29 13:00:00.000000', NULL, 1),
(95817, 3808, 2223, '<td valign="top">Love the colors....</td>', 'Love the colors....', '2002-07-29 13:12:00.000000', NULL, 1),
(95818, 3808, 2000, '<td valign="top">Nice Photoshopping.  Nothing else to say.</td>', 'Nice Photoshopping.  Nothing else to say.', '2002-07-29 14:22:00.000000', NULL, 1),
(95819, 3808, 436, '<td valign="top">I like the color treatment</td>', 'I like the color treatment', '2002-07-29 14:40:00.000000', NULL, 1),
(95820, 3808, 2295, '<td valign="top">Great photo.  I like what you did to the color.  Focus is good, lighting is good.  Subject matter is good.  8...</td>', 'Great photo.  I like what you did to the color.  Focus is good, lighting is good.  Subject matter is good.  8...', '2002-07-29 14:59:00.000000', NULL, 1),
(95821, 3808, 210, '<td valign="top">Fun with photoshop, eh?</td>', 'Fun with photoshop, eh?', '2002-07-29 15:32:00.000000', NULL, 1),
(95822, 3808, 2553, '<td valign="top">Very, very cool!! How did you do that??????????  I love it, and it''s totally corporate to me. Great job! lhall</td>', 'Very, very cool!! How did you do that??????????  I love it, and it''s totally corporate to me. Great job! lhall', '2002-07-29 15:36:00.000000', NULL, 1),
(95823, 3808, 2586, '<td valign="top">It does meet the challenge and I do like the title. Just find the manipulations overdone</td>', 'It does meet the challenge and I do like the title. Just find the manipulations overdone', '2002-07-29 17:26:00.000000', NULL, 1),
(95824, 3808, 2983, '<td valign="top">It looks like you used a posterization/color-channel quantization effect.  I personally feel this effect works best with more abstract subject matter or daring composition.  It might have worked better for me if you got closer to the building, and used a more interesting camera angle.</td>', 'It looks like you used a posterization/color-channel quantization effect.  I personally feel this effect works best with more abstract subject matter or daring composition.  It might have worked better for me if you got closer to the building, and used a more interesting camera angle.', '2002-07-29 19:25:00.000000', NULL, 1),
(95825, 3808, 1569, '<td valign="top">I think you over did it a little.I would like to see this building as a straight print--its really interesting.</td>', 'I think you over did it a little.I would like to see this building as a straight print--its really interesting.', '2002-07-29 22:03:00.000000', NULL, 1),
(95826, 3808, 244, '<td valign="top">Intresting use of solarize with this picture, I think it really works here.  Looks like you have some vinetting on the top corners of your picture don''t know if it was intentional but it is a little distracting.  The way the colors are here really suggests the dullness of the corprate world when surrounded by the gradure of a sunset. Nice job one of my favorites.  Score 8  ------- Corey</td>', 'Intresting use of solarize with this picture, I think it really works here.  Looks like you have some vinetting on the top corners of your picture don''t know if it was intentional but it is a little distracting.  The way the colors are here really suggests the dullness of the corprate world when surrounded by the gradure of a sunset. Nice job one of my favorites.  Score 8  ------- Corey', '2002-07-29 23:27:00.000000', NULL, 1),
(95827, 3808, 2278, '<td valign="top">Whoa!  Too much manipulation.  I think I would have really liked this photo in it''s original form.</td>', 'Whoa!  Too much manipulation.  I think I would have really liked this photo in it''s original form.', '2002-07-30 01:48:00.000000', NULL, 1),
(95828, 3808, 2791, '<td valign="top">is that from a digital camera? if yes, how to do that?</td>', 'is that from a digital camera? if yes, how to do that?', '2002-07-30 07:04:00.000000', NULL, 1),
(95829, 3808, 2858, '<td valign="top">I like the colours in this picture. It could possibly be  improved by sticking with the colour range in the bottom third, through desaturation or less contrast. Possibly a bit too much of a battle between orange/red and the blue at the top, making it imbalanced.</td>', 'I like the colours in this picture. It could possibly be  improved by sticking with the colour range in the bottom third, through desaturation or less contrast. Possibly a bit too much of a battle between orange/red and the blue at the top, making it imbalanced.', '2002-07-30 08:22:00.000000', NULL, 1),
(95830, 3808, 2928, '<td valign="top">Very artistic and it fits the challenge But there is something I can''t quite put my finger on with this picture Sorry, but I''m not sure what it is that I don''t like about it.  Perhaps it is the filter that detracts from the overall picture.  Hopefully, the other voters will be a little more constructive</td>', 'Very artistic and it fits the challenge But there is something I can''t quite put my finger on with this picture Sorry, but I''m not sure what it is that I don''t like about it.  Perhaps it is the filter that detracts from the overall picture.  Hopefully, the other voters will be a little more constructive', '2002-07-30 11:41:00.000000', NULL, 1),
(95831, 3808, 573, '<td valign="top">Very colorfull save for what I am guessing was a rather dull pictrure.   Could you send me a ''how to'', most of my pictures could benifit from this technique.  :-)<br/>I like it, one of my top picks.</td>', 'Very colorfull save for what I am guessing was a rather dull pictrure.   Could you send me a ''how to'', most of my pictures could benifit from this technique.  :-)I like it, one of my top picks.', '2002-07-30 12:39:00.000000', NULL, 1),
(95832, 3808, 1175, '<td valign="top">I kinda like.  I don''t like the posterize effect too much.  I do like the heavy saturation though.</td>', 'I kinda like.  I don''t like the posterize effect too much.  I do like the heavy saturation though.', '2002-07-30 20:00:00.000000', NULL, 1),
(95833, 3808, 133, '<td valign="top">Good use of a filter.  It adds color and contrast to this photo.</td>', 'Good use of a filter.  It adds color and contrast to this photo.', '2002-07-31 08:41:00.000000', NULL, 1),
(95834, 3808, 2261, '<td valign="top">I like the colour effects on this. Good image.</td>', 'I like the colour effects on this. Good image.', '2002-07-31 13:53:00.000000', NULL, 1),
(95835, 3808, 1019, '<td valign="top">Clever and interesting post processing</td>', 'Clever and interesting post processing', '2002-07-31 15:37:00.000000', NULL, 1),
(95836, 3808, 1856, '<td valign="top">i really like the wacky colors and textures here...looks toxic!  I even like the slight crookedness of the angle/leaning building.  8 LIsa</td>', 'i really like the wacky colors and textures here...looks toxic!  I even like the slight crookedness of the angle/leaning building.  8 LIsa', '2002-07-31 20:55:00.000000', NULL, 1),
(95837, 3808, 255, '<td valign="top">nice and artsy. reminds me of a grateful dead or pink floyd cover! nice use of overprocessing. 9--amitchell</td>', 'nice and artsy. reminds me of a grateful dead or pink floyd cover! nice use of overprocessing. 9--amitchell', '2002-08-01 02:09:00.000000', NULL, 1),
(95838, 3808, 472, '<td valign="top">truly incredible effect. i guess this is a posterize of some kind.  it looks like an incredible combination of a drawing and photo. like monty python or ralph bakshi, or Pink Floyd''s the Wall.  it ''s a little tilted to the right... love it. 8. mag99.</td>', 'truly incredible effect. i guess this is a posterize of some kind.  it looks like an incredible combination of a drawing and photo. like monty python or ralph bakshi, or Pink Floyd''s the Wall.  it ''s a little tilted to the right... love it. 8. mag99.', '2002-08-01 23:46:00.000000', NULL, 1),
(95839, 3808, 875, '<td valign="top">I love the post-processing on this!</td>', 'I love the post-processing on this!', '2002-08-02 00:07:00.000000', NULL, 1),
(95840, 3808, 2310, '<td valign="top">I love the cranking up of the different levels. -10</td>', 'I love the cranking up of the different levels. -10', '2002-08-02 13:05:00.000000', NULL, 1),
