(96003, 3821, 2154, '<td valign="top">FINE PIX....NEEDS A BETTER TITLE</td>', 'FINE PIX....NEEDS A BETTER TITLE', '2002-07-31 04:44:00.000000', NULL, 1),
(96004, 3821, 133, '<td valign="top">Clear and sharp photograph.</td>', 'Clear and sharp photograph.', '2002-07-31 09:07:00.000000', NULL, 1),
(96005, 3821, 121, '<td valign="top">Lovely composition. I like the way every item is crisp and that you used a new note instead of that scruffy one in your pocket. Nice job. I presume the Charge in the title refers to a criminal charge.  I have no idea what colour a $10 note is but for some reason I didn''t think it would be that colour.</td>', 'Lovely composition. I like the way every item is crisp and that you used a new note instead of that scruffy one in your pocket. Nice job. I presume the Charge in the title refers to a criminal charge.  I have no idea what colour a $10 note is but for some reason I didn''t think it would be that colour.', '2002-07-31 17:12:00.000000', NULL, 1),
(96006, 3821, 472, '<td valign="top">great sharpness and detail.</td>', 'great sharpness and detail.', '2002-08-01 23:55:00.000000', NULL, 1),
(96007, 3821, 737, '<td valign="top">Composition - quite good<br/>Technical Aspects - very good<br/>Meets Challenge - yes<br/>Visual Impact / Originality - quite good<br/></td>', 'Composition - quite goodTechnical Aspects - very goodMeets Challenge - yesVisual Impact / Originality - quite good', '2002-08-04 23:26:00.000000', NULL, 1),
(96008, 3824, 1792, '<td valign="top">Effective.  The message is there and the photo is well done.</td>', 'Effective.  The message is there and the photo is well done.', '2002-07-29 02:11:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(96009, 3824, 1793, '<td valign="top">that''s some awesome still work, but i have problems connecting it to the challenge.</td>', 'that''s some awesome still work, but i have problems connecting it to the challenge.', '2002-07-29 02:22:00.000000', NULL, 1),
(96010, 3824, 671, '<td valign="top">excellent symbolism!  Great creativity in choice of subject.  Great composition, lighting.</td>', 'excellent symbolism!  Great creativity in choice of subject.  Great composition, lighting.', '2002-07-29 10:25:00.000000', NULL, 1),
(96011, 3824, 1856, '<td valign="top">Very original idea!  I wish there were some way for you to imply the 401k thing in the photo though...love it all the same.  9 Lisa</td>', 'Very original idea!  I wish there were some way for you to imply the 401k thing in the photo though...love it all the same.  9 Lisa', '2002-07-29 16:17:00.000000', NULL, 1),
(96012, 3824, 2586, '<td valign="top">Beautiful, beautiful  image but other than the title has nothing to do with the challenge. Now, if you have thrown in a copy of your 401K statement or something like that it would have helped a lot.</td>', 'Beautiful, beautiful  image but other than the title has nothing to do with the challenge. Now, if you have thrown in a copy of your 401K statement or something like that it would have helped a lot.', '2002-07-29 17:29:00.000000', NULL, 1),
(96013, 3824, 441, '<td valign="top">good concept well expressed 8</td>', 'good concept well expressed 8', '2002-07-29 19:01:00.000000', NULL, 1),
(96014, 3824, 2983, '<td valign="top">I like the lighting tones, but it could use a bit more contrast.</td>', 'I like the lighting tones, but it could use a bit more contrast.', '2002-07-29 19:20:00.000000', NULL, 1),
(96015, 3824, 2649, '<td valign="top">Good idea &amp; photo is excellent.</td>', 'Good idea & photo is excellent.', '2002-07-29 23:48:00.000000', NULL, 1),
(96016, 3824, 2798, '<td valign="top">Unclear weather this nest egg hatched or was broken. The feathers are too large and distracting. I like your concept a lot but it needed a little more development. Also things are a little dark - you only have 1 light source and I think you could have used a second or third.</td>', 'Unclear weather this nest egg hatched or was broken. The feathers are too large and distracting. I like your concept a lot but it needed a little more development. Also things are a little dark - you only have 1 light source and I think you could have used a second or third.', '2002-07-30 09:12:00.000000', NULL, 1),
(96017, 3824, 573, '<td valign="top">Very on topic, many lost everything for the gain of a few.  IMO great use of the required blank space,  would you have used a square format if it were allowed?  One of my top ten picks this challenge.</td>', 'Very on topic, many lost everything for the gain of a few.  IMO great use of the required blank space,  would you have used a square format if it were allowed?  One of my top ten picks this challenge.', '2002-07-30 12:59:00.000000', NULL, 1),
(96018, 3824, 436, '<td valign="top">The basket fades nicely into the dark background.  If moss had been available to you, like the gren kind that comes in the plastic bags at the craft store, or spanish moss, or soemthing a bit more natural to bscure the upper rim of the basket, I''d have liked that aspect better.  The shells and feathers and nicely placed, showing our little egg has taken flight.  Placement inthe lower left is a nice touch, too.  8 crisa58</td>', 'The basket fades nicely into the dark background.  If moss had been available to you, like the gren kind that comes in the plastic bags at the craft store, or spanish moss, or soemthing a bit more natural to bscure the upper rim of the basket, I''d have liked that aspect better.  The shells and feathers and nicely placed, showing our little egg has taken flight.  Placement inthe lower left is a nice touch, too.  8 crisa58', '2002-07-30 14:15:00.000000', NULL, 1),
(96019, 3824, 835, '<td valign="top">Perfect 10</td>', 'Perfect 10', '2002-07-30 18:37:00.000000', NULL, 1),
(96020, 3824, 210, '<td valign="top">Absolutely love this, even though the title had to explain it.  A bit centered would have been better, I think.  8.</td>', 'Absolutely love this, even though the title had to explain it.  A bit centered would have been better, I think.  8.', '2002-07-30 19:35:00.000000', NULL, 1),
(96021, 3824, 1003, '<td valign="top">isn''t this the truth........</td>', 'isn''t this the truth........', '2002-07-30 19:38:00.000000', NULL, 1),
(96022, 3824, 3014, '<td valign="top">Ouch! So where''s the yolk?</td>', 'Ouch! So where''s the yolk?', '2002-07-31 03:25:00.000000', NULL, 1),
(96023, 3824, 1169, '<td valign="top">its okay, its a bit hard to interpreate</td>', 'its okay, its a bit hard to interpreate', '2002-07-31 04:35:00.000000', NULL, 1),
(96024, 3824, 133, '<td valign="top">Seems like this photo needs something indicating your title besides just a nest.  Perhaps some money.</td>', 'Seems like this photo needs something indicating your title besides just a nest.  Perhaps some money.', '2002-07-31 08:59:00.000000', NULL, 1),
(96025, 3824, 1280, '<td valign="top">Good, strong symbolism, well composed.  A simple concept, well planned and executed.  Meets the challenge head on.   This is a good picture that needs no explanation. Very, very nicely done.  I see one little thing that upsets my apple cart.  The vertical item,  behind the broken egg, is it a feather?  A paper shard?  If it''s important to the overall image, then  this object should be  in focus; otherwise why not remove it from the composition? Just something to consider.  9  Gracious<br/></td>', 'Good, strong symbolism, well composed.  A simple concept, well planned and executed.  Meets the challenge head on.   This is a good picture that needs no explanation. Very, very nicely done.  I see one little thing that upsets my apple cart.  The vertical item,  behind the broken egg, is it a feather?  A paper shard?  If it''s important to the overall image, then  this object should be  in focus; otherwise why not remove it from the composition? Just something to consider.  9  Gracious', '2002-07-31 21:43:00.000000', NULL, 1),
(96026, 3824, 875, '<td valign="top">Very cute!  I would have liked a little something more on the right side of the frame - maybe another feather or more eggshell pieces a bit to the right of the existing feather.</td>', 'Very cute!  I would have liked a little something more on the right side of the frame - maybe another feather or more eggshell pieces a bit to the right of the existing feather.', '2002-08-01 18:38:00.000000', NULL, 1),
(96027, 3824, 3063, '<td valign="top">No comment necessary....the photo says it all!</td>', 'No comment necessary....the photo says it all!', '2002-08-02 12:41:00.000000', NULL, 1),
(96028, 3824, 811, '<td valign="top">The only two things I can comment negatively are the darkness (seems a little too much for me), and it is tilted a little to the left, it seems, making me feel unbalanced (which works with the picture).  I like the idea and how you have set it up.  One of my highest scores this week. karmat</td>', 'The only two things I can comment negatively are the darkness (seems a little too much for me), and it is tilted a little to the left, it seems, making me feel unbalanced (which works with the picture).  I like the idea and how you have set it up.  One of my highest scores this week. karmat', '2002-08-03 11:05:00.000000', NULL, 1),
(96029, 3824, 806, '<td valign="top">This is a beautifully composed photograph. Have to say that the title explains it for this challenge, although it''s obviously meeting it too... Hmm. ... Otherwise it could mean a number of things... (8)</td>', 'This is a beautifully composed photograph. Have to say that the title explains it for this challenge, although it''s obviously meeting it too... Hmm. ... Otherwise it could mean a number of things... (8)', '2002-08-04 00:56:00.000000', NULL, 1),
(96030, 3824, 737, '<td valign="top">Composition - quite good<br/>Technical Aspects - quite good<br/>Meets Challenge - yes<br/>Visual Impact / Originality - good<br/></td>', 'Composition - quite goodTechnical Aspects - quite goodMeets Challenge - yesVisual Impact / Originality - good', '2002-08-04 23:48:00.000000', NULL, 1),
(96031, 3824, 2752, '<td valign="top">I couldn''t be more pleased with the results.  I''m too old to have 401ks as  some suggested I should have placed in the nest and don''t live in a city or have access to newspapers...but I did have a little "nest egg" once.  Thanks to all for your constructive comments.</td>', 'I couldn''t be more pleased with the results.  I''m too old to have 401ks as  some suggested I should have placed in the nest and don''t live in a city or have access to newspapers...but I did have a little "nest egg" once.  Thanks to all for your constructive comments.', '2002-08-05 01:35:00.000000', NULL, 0),
(96032, 3824, 2798, '<td valign="top">What''s a 401k?</td>', 'What''s a 401k?', '2002-08-05 11:01:00.000000', NULL, 0),
(96033, 3824, 2752, '<td valign="top">Floyd, 401K''s are options  for people in the work force to invest part of their paychecks into mutual funds.  Most companies match the emplyee.  In Canada they are called RRSP''s.   When I quit work many years ago IRA''s were the option in the USA.</td>', 'Floyd, 401K''s are options  for people in the work force to invest part of their paychecks into mutual funds.  Most companies match the emplyee.  In Canada they are called RRSP''s.   When I quit work many years ago IRA''s were the option in the USA.', '2002-08-05 12:02:00.000000', NULL, 0),
(96034, 3824, 1280, '<td valign="top">For some reason I can now decipher the vertical feather behind the egg.  Sorry I just didn''t see it clearly before....dunno why.  This is a very good picture!</td>', 'For some reason I can now decipher the vertical feather behind the egg.  Sorry I just didn''t see it clearly before....dunno why.  This is a very good picture!', '2002-08-05 18:38:00.000000', NULL, 0),
(96035, 3825, 2567, '<td valign="top">good composition 8</td>', 'good composition 8', '2002-07-29 01:42:00.000000', NULL, 1),
(96036, 3825, 92, '<td valign="top">One dollar at a time....</td>', 'One dollar at a time....', '2002-07-29 03:15:00.000000', NULL, 1),
(96037, 3825, 2780, '<td valign="top">Very nice idea, executed very well. I think it would perhaps look better of there wasnt blood actually on the nail, because really there would be no blood there, it would just be oozing out the money. I think also that if you wanted a black background that it should actually be BLACK, not this dark grey colour. You just needed to take the brightness down a little bit in photoshop. Overall I gave this 7.</td>', 'Very nice idea, executed very well. I think it would perhaps look better of there wasnt blood actually on the nail, because really there would be no blood there, it would just be oozing out the money. I think also that if you wanted a black background that it should actually be BLACK, not this dark grey colour. You just needed to take the brightness down a little bit in photoshop. Overall I gave this 7.', '2002-07-29 05:45:00.000000', NULL, 1),
(96038, 3825, 142, '<td valign="top">Great Idea!  I love the message of this photo. 10</td>', 'Great Idea!  I love the message of this photo. 10', '2002-07-29 12:14:00.000000', NULL, 1),
(96039, 3825, 2981, '<td valign="top">artistic idea</td>', 'artistic idea', '2002-07-29 13:43:00.000000', NULL, 1),
(96040, 3825, 1983, '<td valign="top">Great photo... Very creative..10</td>', 'Great photo... Very creative..10', '2002-07-29 13:57:00.000000', NULL, 1),
(96041, 3825, 2553, '<td valign="top">In my opinion the nail should have been through a credit card, since that is where most people are being bled dry! Good composition, lighting, I like this shot because, to me, it is almost visceral. lhall</td>', 'In my opinion the nail should have been through a credit card, since that is where most people are being bled dry! Good composition, lighting, I like this shot because, to me, it is almost visceral. lhall', '2002-07-29 14:45:00.000000', NULL, 1),
(96042, 3825, 1005, '<td valign="top">Very clear shot.  (was any money "hurt" in this production?)  I like the angle of the bill, nice interest.  Good amount of negative space.  (gotta learn that myself)  The closest thing I have to a critical (bad) comment is the head of the nail.....pretty picky.  Mine is a money shot, too, so I think the challenge was met.  9 Swash</td>', 'Very clear shot.  (was any money "hurt" in this production?)  I like the angle of the bill, nice interest.  Good amount of negative space.  (gotta learn that myself)  The closest thing I have to a critical (bad) comment is the head of the nail.....pretty picky.  Mine is a money shot, too, so I think the challenge was met.  9 Swash', '2002-07-29 16:58:00.000000', NULL, 1),
(96043, 3825, 2752, '<td valign="top">very dramatic use of symbols</td>', 'very dramatic use of symbols', '2002-07-29 18:02:00.000000', NULL, 1),
(96044, 3825, 117, '<td valign="top">what the treasury going to say about defacing all these bills nice concept</td>', 'what the treasury going to say about defacing all these bills nice concept', '2002-07-29 19:58:00.000000', NULL, 1),
(96045, 3825, 2352, '<td valign="top">Clever idea!  nice clean shot!</td>', 'Clever idea!  nice clean shot!', '2002-07-29 23:01:00.000000', NULL, 1),
(96046, 3825, 2791, '<td valign="top">WOW!!! what a nice idea!!! :)</td>', 'WOW!!! what a nice idea!!! :)', '2002-07-30 06:39:00.000000', NULL, 1),
(96047, 3825, 2798, '<td valign="top">Good focus and composition. Lighting is a little uninteresting, though.</td>', 'Good focus and composition. Lighting is a little uninteresting, though.', '2002-07-30 08:58:00.000000', NULL, 1),
(96048, 3825, 1859, '<td valign="top">Well thought out and executed.</td>', 'Well thought out and executed.', '2002-07-30 18:04:00.000000', NULL, 1),
(96049, 3825, 835, '<td valign="top">very crisp</td>', 'very crisp', '2002-07-30 18:28:00.000000', NULL, 1),
(96050, 3825, 2109, '<td valign="top">Killing for a $1 bill?  c''mon!!  Show me a $1000 with real blood on it, then we''ll have something.</td>', 'Killing for a $1 bill?  c''mon!!  Show me a $1000 with real blood on it, then we''ll have something.', '2002-07-30 22:29:00.000000', NULL, 1),
(96051, 3825, 737, '<td valign="top">Composition - very good<br/>Technical Aspects - very good<br/>Meets Challenge - sort of<br/>Visual Impact / Originality - high<br/></td>', 'Composition - very goodTechnical Aspects - very goodMeets Challenge - sort ofVisual Impact / Originality - high', '2002-07-31 00:40:00.000000', NULL, 1),
(96052, 3825, 3014, '<td valign="top">A blue denim shirt behind that dollar would make the blood more poignant.</td>', 'A blue denim shirt behind that dollar would make the blood more poignant.', '2002-07-31 02:56:00.000000', NULL, 1),
(96053, 3825, 2928, '<td valign="top">This is a great idea; the blood money idea is inventive, the picture quality and composition is spot on and (I think) this could have been a winning picture but for one fatal flaw  the blood doesn''t look real enough.  I can''t be more specific, and perhaps other voters wont be quite so pedantic, but for me personally, it spoils the whole picture  sorry</td>', 'This is a great idea; the blood money idea is inventive, the picture quality and composition is spot on and (I think) this could have been a winning picture but for one fatal flaw  the blood doesn''t look real enough.  I can''t be more specific, and perhaps other voters wont be quite so pedantic, but for me personally, it spoils the whole picture  sorry', '2002-07-31 06:19:00.000000', NULL, 1),
(96054, 3825, 1856, '<td valign="top">blood money...nice.  I like the fitting look in George''s eye...can''t put it into words but it seems to go well with being nailed.  Could have used a little more focus on the nail (I played with something similar this week and had a similar annoying problem with focus on the ''nail.''  I think the texture on the black fabric detracts a little too.  6</td>', 'blood money...nice.  I like the fitting look in George''s eye...can''t put it into words but it seems to go well with being nailed.  Could have used a little more focus on the nail (I played with something similar this week and had a similar annoying problem with focus on the ''nail.''  I think the texture on the black fabric detracts a little too.  6', '2002-07-31 20:14:00.000000', NULL, 1),
(96055, 3825, 1280, '<td valign="top">Very effective picture, well composed with good detail, lighting, color saturation. Very good.  Congratulations!  10  Gracious</td>', 'Very effective picture, well composed with good detail, lighting, color saturation. Very good.  Congratulations!  10  Gracious', '2002-07-31 21:29:00.000000', NULL, 1),
(96056, 3825, 2997, '<td valign="top">dramatically, visually succinct!  Not sure what it has to do with the theme.</td>', 'dramatically, visually succinct!  Not sure what it has to do with the theme.', '2002-08-01 17:17:00.000000', NULL, 1),
(96057, 3825, 472, '<td valign="top">very powerful statement.  some have probably blasted you but they are fools :).  few ways to improve this, most involving maybe some more dramatic lighting choices with a bit more shadow on the nail. . . otherwise excellent. 8. mag99</td>', 'very powerful statement.  some have probably blasted you but they are fools :).  few ways to improve this, most involving maybe some more dramatic lighting choices with a bit more shadow on the nail. . . otherwise excellent. 8. mag99', '2002-08-01 23:42:00.000000', NULL, 1),
(96058, 3825, 1882, '<td valign="top">WEll done.</td>', 'WEll done.', '2002-08-02 09:31:00.000000', NULL, 1),
(96059, 3825, 2261, '<td valign="top">If the nail was sharper this would be brilliant! Great idea though, simple yet packs a punch.</td>', 'If the nail was sharper this would be brilliant! Great idea though, simple yet packs a punch.', '2002-08-03 12:38:00.000000', NULL, 1),
(96060, 3825, 2009, '<td valign="top">Neat idea but I believe that is illeagal.</td>', 'Neat idea but I believe that is illeagal.', '2002-08-03 22:29:00.000000', NULL, 1),
(96061, 3825, 2837, '<td valign="top">What did you use for the blood?</td>', 'What did you use for the blood?', '2002-08-04 03:55:00.000000', NULL, 1),
(96062, 3825, 3087, '<td valign="top">I like the idea and the image is nice and crisp but the composition doesn''t work well for me.</td>', 'I like the idea and the image is nice and crisp but the composition doesn''t work well for me.', '2002-08-04 17:21:00.000000', NULL, 1),
(96063, 3825, 2247, '<td valign="top">"Corporations make a killing."  So true.  Too many big businesses have built their profiits on the "BLOOD, sweat, and tears" of the working man.  Your pic is chilling commentary of that attitude.</td>', '"Corporations make a killing."  So true.  Too many big businesses have built their profiits on the "BLOOD, sweat, and tears" of the working man.  Your pic is chilling commentary of that attitude.', '2002-08-04 23:04:00.000000', NULL, 1),
(96064, 3826, 2596, '<td valign="top">Good picture if it were in focus</td>', 'Good picture if it were in focus', '2002-07-29 03:29:00.000000', NULL, 1),
(96065, 3826, 2780, '<td valign="top">7:-<br/>It is a well set up photograph that shows the topic matter in a fairly good way. I think however that the photo it a bit blurred, where the camera has been moved or something, and it has tried to be sharpened in photoshop, although that adds a horrible grain to the photo.</td>', '7:-It is a well set up photograph that shows the topic matter in a fairly good way. I think however that the photo it a bit blurred, where the camera has been moved or something, and it has tried to be sharpened in photoshop, although that adds a horrible grain to the photo.', '2002-07-29 05:41:00.000000', NULL, 1),
(96066, 3826, 811, '<td valign="top">I like the colors in this, and the idea is good.  I think, however, you almost have two separate pictures going on.  I would have preferred it without the watch. karmat</td>', 'I like the colors in this, and the idea is good.  I think, however, you almost have two separate pictures going on.  I would have preferred it without the watch. karmat', '2002-07-29 15:12:00.000000', NULL, 1),
(96067, 3826, 1944, '<td valign="top">Nice product shot.</td>', 'Nice product shot.', '2002-07-29 15:14:00.000000', NULL, 1),
(96068, 3826, 2752, '<td valign="top">good design and use of colors</td>', 'good design and use of colors', '2002-07-29 18:21:00.000000', NULL, 1),
(96069, 3826, 1569, '<td valign="top">The only thing detracting from this pix is the out of focus watch face.</td>', 'The only thing detracting from this pix is the out of focus watch face.', '2002-07-29 21:41:00.000000', NULL, 1),
(96070, 3826, 2798, '<td valign="top">A bit too literal for my tastes. Also the focus seems a bit off. The lighting is ok but not very dramatic. Those CDs could be giving us more colour.</td>', 'A bit too literal for my tastes. Also the focus seems a bit off. The lighting is ok but not very dramatic. Those CDs could be giving us more colour.', '2002-07-30 09:33:00.000000', NULL, 1),
(96071, 3826, 2928, '<td valign="top">Hmmm  great picture, well lit and fits the challenge.  I would say it''s a bit too clinical, but then, so is capitalism (8)</td>', 'Hmmm  great picture, well lit and fits the challenge.  I would say it''s a bit too clinical, but then, so is capitalism (8)', '2002-07-30 11:48:00.000000', NULL, 1),
(96072, 3826, 1005, '<td valign="top">Title?  I think it resembles your photo, a bit jumbled.  I would call this a little bit of a reach for this challenge.  The photo is well taken.  The focus is pretty good (the watch face seems "off" just a bit.  Framing is too much of a personal choice to me, I prefer to not cut off subjects, but this is acceptable.  I like the reflection of the watch in the CD.  I''m not crazy about the carpet, but you make due with what you have on hand.  As a just plain photo, it''s about a 7, as a challenge photo, about the best I can go is 5.  Swash</td>', 'Title?  I think it resembles your photo, a bit jumbled.  I would call this a little bit of a reach for this challenge.  The photo is well taken.  The focus is pretty good (the watch face seems "off" just a bit.  Framing is too much of a personal choice to me, I prefer to not cut off subjects, but this is acceptable.  I like the reflection of the watch in the CD.  I''m not crazy about the carpet, but you make due with what you have on hand.  As a just plain photo, it''s about a 7, as a challenge photo, about the best I can go is 5.  Swash', '2002-07-30 19:42:00.000000', NULL, 1),
(96073, 3826, 2146, '<td valign="top">cool abstract</td>', 'cool abstract', '2002-07-31 07:43:00.000000', NULL, 1),
(96074, 3826, 637, '<td valign="top">Don''t understand your title or your intention. 3 sjgleah</td>', 'Don''t understand your title or your intention. 3 sjgleah', '2002-08-01 06:52:00.000000', NULL, 1),
(96075, 3826, 472, '<td valign="top">i really like the composition but i find the background color really doesn''t go with the other colors.  something more simple would probably have enhanced the picture greatly.  mag99</td>', 'i really like the composition but i find the background color really doesn''t go with the other colors.  something more simple would probably have enhanced the picture greatly.  mag99', '2002-08-01 23:44:00.000000', NULL, 1),
