(96338, 3849, 2170, '<td valign="top">Is the money supposed to represent the only bit that''s left?</td>', 'Is the money supposed to represent the only bit that''s left?', '2002-07-29 01:13:00.000000', NULL, 1),
(96339, 3849, 2586, '<td valign="top">You are effective in getting your message across here but you are not doing it in a particularly beautiful way. Don''t care for the composition, particularly the top two pages of the WSJ and all that change. The change is in the foreground and too dark and out of focus. With fewer objects and a better arrangement of them you would have had a much better picture. Good idea though.</td>', 'You are effective in getting your message across here but you are not doing it in a particularly beautiful way. Don''t care for the composition, particularly the top two pages of the WSJ and all that change. The change is in the foreground and too dark and out of focus. With fewer objects and a better arrangement of them you would have had a much better picture. Good idea though.', '2002-07-29 02:43:00.000000', NULL, 1),
(96340, 3849, 92, '<td valign="top">I think this about sums it up:) Nice job.= 8 Shiiizzzam</td>', 'I think this about sums it up:) Nice job.= 8 Shiiizzzam', '2002-07-29 02:48:00.000000', NULL, 1),
