(96403, 3852, 2798, '<td valign="top">Again it''s tenuous to tie a picture of a tent to this challenge just through the title. But it''s a reasonable picture of an internally lit tent. Perhaps a longer exposure would have shown us just a little of the surrounding terrain.</td>', 'Again it''s tenuous to tie a picture of a tent to this challenge just through the title. But it''s a reasonable picture of an internally lit tent. Perhaps a longer exposure would have shown us just a little of the surrounding terrain.', '2002-07-30 10:13:00.000000', NULL, 1),
(96404, 3852, 2109, '<td valign="top">hahaha  .. good for a laugh, according to the title.</td>', 'hahaha  .. good for a laugh, according to the title.', '2002-07-30 22:20:00.000000', NULL, 1),
(96405, 3852, 3014, '<td valign="top">Don''t let the title tell the story, let the photo tell it. This is a nice ad shot for the tent manufacturer, but without a briefcase, a notebook computer, a cell phone, and perhaps a suit or tie nearby, it doesn''t say corporate at all.</td>', 'Don''t let the title tell the story, let the photo tell it. This is a nice ad shot for the tent manufacturer, but without a briefcase, a notebook computer, a cell phone, and perhaps a suit or tie nearby, it doesn''t say corporate at all.', '2002-07-30 23:30:00.000000', NULL, 1),
(96406, 3852, 1856, '<td valign="top">I really like the colors and contrast here....the peak of green grass in the black is a nice touch too.  I can almost hear the crickets.  I wish the enron logo were on the tent and there was a shredder parked outside though.  The photo doesn''t speak ''corp world'' to me at all w/o the title.  7 Lisa</td>', 'I really like the colors and contrast here....the peak of green grass in the black is a nice touch too.  I can almost hear the crickets.  I wish the enron logo were on the tent and there was a shredder parked outside though.  The photo doesn''t speak ''corp world'' to me at all w/o the title.  7 Lisa', '2002-07-30 23:37:00.000000', NULL, 1),
(96407, 3852, 2146, '<td valign="top">I love the colors, very well focused...nice</td>', 'I love the colors, very well focused...nice', '2002-07-31 07:58:00.000000', NULL, 1),
(96408, 3852, 133, '<td valign="top">Ha. Clever.</td>', 'Ha. Clever.', '2002-07-31 09:03:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(96409, 3852, 121, '<td valign="top">Very nicely done, lovely colours and well exposed. Perfect lighting. Maybe you wer trying to give the impression of a big dark open space surrounding the tent otherwise I  might have been tempted to crop a bit from top , left and bottom. Not a big issue though and I like it the way it is.</td>', 'Very nicely done, lovely colours and well exposed. Perfect lighting. Maybe you wer trying to give the impression of a big dark open space surrounding the tent otherwise I  might have been tempted to crop a bit from top , left and bottom. Not a big issue though and I like it the way it is.', '2002-07-31 16:22:00.000000', NULL, 1),
(96410, 3852, 2251, '<td valign="top">To learn more about the detramental effects of capitalism and statism, go to www.infoshop.org<br/>-Ben</td>', 'To learn more about the detramental effects of capitalism and statism, go to www.infoshop.org-Ben', '2002-07-31 18:46:00.000000', NULL, 1),
(96411, 3852, 637, '<td valign="top">Amusing, but contrived.  Technically sound. 4 sjgleah</td>', 'Amusing, but contrived.  Technically sound. 4 sjgleah', '2002-08-01 06:17:00.000000', NULL, 1),
(96412, 3852, 2900, '<td valign="top">Neat Picture, but it doesn''t really fit the challange.</td>', 'Neat Picture, but it doesn''t really fit the challange.', '2002-08-01 21:48:00.000000', NULL, 1),
(96413, 3852, 2370, '<td valign="top">haha..very funny..</td>', 'haha..very funny..', '2002-08-02 01:38:00.000000', NULL, 1),
(96414, 3852, 811, '<td valign="top">I love the humor behind this, the colors, focus, etc.  Maybe you should have had someone at a desk or something as a silhouette. karmat</td>', 'I love the humor behind this, the colors, focus, etc.  Maybe you should have had someone at a desk or something as a silhouette. karmat', '2002-08-02 23:48:00.000000', NULL, 1),
(96415, 3852, 2932, '<td valign="top">clever and colorful.  kind of a stretch, as without the title it would appear off-topic</td>', 'clever and colorful.  kind of a stretch, as without the title it would appear off-topic', '2002-08-03 02:28:00.000000', NULL, 1),
(96416, 3852, 2833, '<td valign="top">I dig the lighting. The name of the photo should not have to explain it. Without it here obviously it would not make sense. So do I rate to title or the photo?</td>', 'I dig the lighting. The name of the photo should not have to explain it. Without it here obviously it would not make sense. So do I rate to title or the photo?', '2002-08-03 15:00:00.000000', NULL, 1),
(96417, 3852, 1330, '<td valign="top">got the biggest laugh out of this one. Only thing I see in my opinion is that it is off center but that is just me.  8</td>', 'got the biggest laugh out of this one. Only thing I see in my opinion is that it is off center but that is just me.  8', '2002-08-04 22:28:00.000000', NULL, 1),
(96418, 3852, 2221, '<td valign="top">nice idea and a good photo. i like the colors and lighting. only sad thing is that the photo only fits to the challenge because of the title. but it''s still a wonderful photo, so i vote it fairly high. maybe an enron logo on the tent would be nice.</td>', 'nice idea and a good photo. i like the colors and lighting. only sad thing is that the photo only fits to the challenge because of the title. but it''s still a wonderful photo, so i vote it fairly high. maybe an enron logo on the tent would be nice.', '2002-08-04 22:44:00.000000', NULL, 1),
(96419, 3852, 2798, '<td valign="top">&amp;gt; I was in the Hoe rain forrest all week. Where was the corporate world? <br/>&amp;gt; Far, far away... What was I suppose to shoot?<br/><br/>How about a colony of ants? Or a rotten tree stump? Or a monkey hanging onto a branch by its finger tips? I think a clever use of metaphor would have had more merit than a ''joke'' photograph. Don''t get me wrong - this photo isn''t bad. But Im disappointed that shots like customer dissatisfaction and the .com bubble scored lower.</td>', '&gt; I was in the Hoe rain forrest all week. Where was the corporate world? &gt; Far, far away... What was I suppose to shoot?How about a colony of ants? Or a rotten tree stump? Or a monkey hanging onto a branch by its finger tips? I think a clever use of metaphor would have had more merit than a ''joke'' photograph. Don''t get me wrong - this photo isn''t bad. But Im disappointed that shots like customer dissatisfaction and the .com bubble scored lower.', '2002-08-05 06:34:00.000000', NULL, 0),
(96420, 3853, 2370, '<td valign="top">not a very interesting subject though..</td>', 'not a very interesting subject though..', '2002-07-29 04:07:00.000000', NULL, 1),
(96421, 3853, 210, '<td valign="top">I think if you''re going to go ahead with this type of layout, it would be better to have them all totally flat.  In the end, I do this the perspective angle definitely helped the image.</td>', 'I think if you''re going to go ahead with this type of layout, it would be better to have them all totally flat.  In the end, I do this the perspective angle definitely helped the image.', '2002-07-29 15:27:00.000000', NULL, 1),
(96422, 3853, 1005, '<td valign="top">Nice "money" shot.  Very clear.  Money to world corporation is a small stretch, all by itself, but I am flexible.....I would have liked some more direct connection, but as presented here, I can''t think of any suggestions.  I am still going to give you an 8.  Swash</td>', 'Nice "money" shot.  Very clear.  Money to world corporation is a small stretch, all by itself, but I am flexible.....I would have liked some more direct connection, but as presented here, I can''t think of any suggestions.  I am still going to give you an 8.  Swash', '2002-07-29 20:40:00.000000', NULL, 1),
(96423, 3853, 1667, '<td valign="top">I really like this picture, but wish the color was more accurate.</td>', 'I really like this picture, but wish the color was more accurate.', '2002-07-29 23:04:00.000000', NULL, 1),
(96424, 3853, 2278, '<td valign="top">Photo seems a little yellowish - whitebalance problems?</td>', 'Photo seems a little yellowish - whitebalance problems?', '2002-07-30 01:41:00.000000', NULL, 1),
(96425, 3853, 2798, '<td valign="top">Not clear on what the concept here is. Nice sharp focus but the light is flat and uninteresting. Composition is fine.</td>', 'Not clear on what the concept here is. Nice sharp focus but the light is flat and uninteresting. Composition is fine.', '2002-07-30 08:49:00.000000', NULL, 1),
(96426, 3853, 2928, '<td valign="top">It''s a sharp, well lit and crisp image and has a lot going for it.  Although, I think it lacks creativity, it is one of those pictures that I am uncertain about  many people may really like this picture and perhaps I am going to be proved wrong</td>', 'It''s a sharp, well lit and crisp image and has a lot going for it.  Although, I think it lacks creativity, it is one of those pictures that I am uncertain about  many people may really like this picture and perhaps I am going to be proved wrong', '2002-07-31 10:14:00.000000', NULL, 1),
(96427, 3853, 2983, '<td valign="top">Color a little washed.  Looks like a white balance / lighting problem.</td>', 'Color a little washed.  Looks like a white balance / lighting problem.', '2002-07-31 12:37:00.000000', NULL, 1),
(96428, 3853, 121, '<td valign="top">It''s a pity you didn''t get two "fresh from the mint" British notes to go with your crisp dollar bill. The folds down both notes spoil the lines. maybe you could have ironed them. The colours look a bit odd also and it is generally dark. There is a lot of room for movement a the bottom end of the level histogram to bring some light and life into this.</td>', 'It''s a pity you didn''t get two "fresh from the mint" British notes to go with your crisp dollar bill. The folds down both notes spoil the lines. maybe you could have ironed them. The colours look a bit odd also and it is generally dark. There is a lot of room for movement a the bottom end of the level histogram to bring some light and life into this.', '2002-07-31 17:25:00.000000', NULL, 1),
(96429, 3853, 811, '<td valign="top">i think this might have been more effective if you had used a horizontal frame and used te bottom half of the American 20 and the top half of the English 20.  karmat</td>', 'i think this might have been more effective if you had used a horizontal frame and used te bottom half of the American 20 and the top half of the English 20.  karmat', '2002-08-02 18:10:00.000000', NULL, 1),
(96430, 3853, 637, '<td valign="top">Yeah, so?  What''s corporate about this?  3 sjgleah</td>', 'Yeah, so?  What''s corporate about this?  3 sjgleah', '2002-08-02 23:11:00.000000', NULL, 1),
(96431, 3854, 210, '<td valign="top">Satirical, but I''m having trouble taking this seriously.  The age of the poser is in question: Arguably too young to be a banker with power.  Also, I ''m guessing you kept the red-eye on purpose to seem devilish.  That, I''m afraid, comes off almost a bit kitchy.  But idea has potential.</td>', 'Satirical, but I''m having trouble taking this seriously.  The age of the poser is in question: Arguably too young to be a banker with power.  Also, I ''m guessing you kept the red-eye on purpose to seem devilish.  That, I''m afraid, comes off almost a bit kitchy.  But idea has potential.', '2002-07-29 02:53:00.000000', NULL, 1),
(96432, 3854, 1360, '<td valign="top">I almost dinged you for the redeye, but, on second thought, it actually makes the subject seem even MORE evil.  The coat could fit better though ;)<br/>The image itself is "average".   I personally hate flashes, and hate what they do to pictures.</td>', 'I almost dinged you for the redeye, but, on second thought, it actually makes the subject seem even MORE evil.  The coat could fit better though ;)The image itself is "average".   I personally hate flashes, and hate what they do to pictures.', '2002-07-29 04:55:00.000000', NULL, 1),
(96433, 3854, 2553, '<td valign="top">I am assuming the red eye to be part of the "feel" of the image, but I would have liked it better without. Would have liked a little closer cropping. The "Corporate" representation is a little off for me - he looks too young to take over anything more than the car keys! lhall</td>', 'I am assuming the red eye to be part of the "feel" of the image, but I would have liked it better without. Would have liked a little closer cropping. The "Corporate" representation is a little off for me - he looks too young to take over anything more than the car keys! lhall', '2002-07-29 06:47:00.000000', NULL, 1),
(96434, 3854, 573, '<td valign="top">This kid SCARES me!!  I am assuming the redeye was accentuated to make the point.  Did you try different backgrounds or no background at all, this one is too busy for my tasts?  When using flash as the main light source pulling the subject away from anything behind them puts the background into darkmess and reduces that glair I see off the back wall of the cabnet.  One of my top picks.</td>', 'This kid SCARES me!!  I am assuming the redeye was accentuated to make the point.  Did you try different backgrounds or no background at all, this one is too busy for my tasts?  When using flash as the main light source pulling the subject away from anything behind them puts the background into darkmess and reduces that glair I see off the back wall of the cabnet.  One of my top picks.', '2002-07-29 11:29:00.000000', NULL, 1),
(96435, 3854, 2752, '<td valign="top">the red eyes are a great devilish addition to your entry</td>', 'the red eyes are a great devilish addition to your entry', '2002-07-29 13:02:00.000000', NULL, 1),
(96436, 3854, 1983, '<td valign="top">Hope you don''t get hammered on the red eye. I wish he was standiing behind a desk instead of in front of the glass case.</td>', 'Hope you don''t get hammered on the red eye. I wish he was standiing behind a desk instead of in front of the glass case.', '2002-07-29 13:44:00.000000', NULL, 1),
(96437, 3854, 2000, '<td valign="top">The red eyes work very well here.</td>', 'The red eyes work very well here.', '2002-07-29 14:37:00.000000', NULL, 1),
(96438, 3854, 436, '<td valign="top">In front of a china cabinet?  Watch your backgrounds!</td>', 'In front of a china cabinet?  Watch your backgrounds!', '2002-07-29 14:43:00.000000', NULL, 1),
(96439, 3854, 2295, '<td valign="top">Nice shot.  KInd of different to actually WANT the red eyes isn''t it?  Focus is good, lighting is good, subject matter is good.  7</td>', 'Nice shot.  KInd of different to actually WANT the red eyes isn''t it?  Focus is good, lighting is good, subject matter is good.  7', '2002-07-29 15:01:00.000000', NULL, 1),
(96440, 3854, 1944, '<td valign="top">Stiff, unrealistic pose. The red-eye doesn''t help.</td>', 'Stiff, unrealistic pose. The red-eye doesn''t help.', '2002-07-29 15:12:00.000000', NULL, 1),
(96441, 3854, 2858, '<td valign="top">One of these times when the red eye effect comes in hamdy!</td>', 'One of these times when the red eye effect comes in hamdy!', '2002-07-29 17:35:00.000000', NULL, 1),
(96442, 3854, 2352, '<td valign="top">clever shot!  The red eye works well for the theme!  Overall lighting could improve instead of head on.  Well done.</td>', 'clever shot!  The red eye works well for the theme!  Overall lighting could improve instead of head on.  Well done.', '2002-07-29 22:05:00.000000', NULL, 1),
(96443, 3854, 2829, '<td valign="top">Definitely fits the theme. One problem I have with this photo is the background. Using something resembling an office or a conference room or perhaps him sitting behind a table would have been a lot better. I think this is the first time I''ve seen someone actually TRY to get red eyes on someone!</td>', 'Definitely fits the theme. One problem I have with this photo is the background. Using something resembling an office or a conference room or perhaps him sitting behind a table would have been a lot better. I think this is the first time I''ve seen someone actually TRY to get red eyes on someone!', '2002-07-29 22:47:00.000000', NULL, 1),
(96444, 3854, 2195, '<td valign="top">too bad they dont allow red eye reduction..the glasses in the background detour the eye away from the subject...maybe a more solid background would help-6</td>', 'too bad they dont allow red eye reduction..the glasses in the background detour the eye away from the subject...maybe a more solid background would help-6', '2002-07-30 09:42:00.000000', NULL, 1),
(96445, 3854, 2891, '<td valign="top">is the red eye on purpose?  background too busy.</td>', 'is the red eye on purpose?  background too busy.', '2002-07-30 10:36:00.000000', NULL, 1),
(96446, 3854, 2983, '<td valign="top">Is the redeye intentional?  Either center the subject and shoot vertical, or choose a more interesting pose.</td>', 'Is the redeye intentional?  Either center the subject and shoot vertical, or choose a more interesting pose.', '2002-07-30 14:35:00.000000', NULL, 1),
(96447, 3854, 772, '<td valign="top">I think your subject makes a good interpretation of the challenge... however, the redeye doesn''t add much for me and the black jacket doesn''t contrast well with the backtround in this image.  This same subject photographed in a brighter environment with less distractions in the background would work much better for me :) - jmsetzler</td>', 'I think your subject makes a good interpretation of the challenge... however, the redeye doesn''t add much for me and the black jacket doesn''t contrast well with the backtround in this image.  This same subject photographed in a brighter environment with less distractions in the background would work much better for me :) - jmsetzler', '2002-07-30 14:46:00.000000', NULL, 1),
(96448, 3854, 1859, '<td valign="top">Where is the red-eye reduction?????????????????  Or was that intentional?  The "devil" look???</td>', 'Where is the red-eye reduction?????????????????  Or was that intentional?  The "devil" look???', '2002-07-30 18:00:00.000000', NULL, 1),
(96449, 3854, 835, '<td valign="top">probably was intentional but I don''t like the red eyes</td>', 'probably was intentional but I don''t like the red eyes', '2002-07-30 19:03:00.000000', NULL, 1),
(96450, 3854, 2109, '<td valign="top">they make red-eye reduction technology now</td>', 'they make red-eye reduction technology now', '2002-07-30 22:38:00.000000', NULL, 1),
(96451, 3854, 806, '<td valign="top">Really busy. Are the red eyes on purpose?</td>', 'Really busy. Are the red eyes on purpose?', '2002-07-30 23:30:00.000000', NULL, 1),
(96452, 3854, 2146, '<td valign="top">awwww the red eye trick...pretty cool</td>', 'awwww the red eye trick...pretty cool', '2002-07-31 07:44:00.000000', NULL, 1),
(96453, 3854, 3020, '<td valign="top">Unsure about the red eye, on one hand distracts from the photo, on the other hand it gives an evil look which I think goes good with the challenge.</td>', 'Unsure about the red eye, on one hand distracts from the photo, on the other hand it gives an evil look which I think goes good with the challenge.', '2002-07-31 08:25:00.000000', NULL, 1),
(96454, 3854, 2997, '<td valign="top">At first I thought the red-eyes detracted from this photo. Then I realized it was very appropriate.</td>', 'At first I thought the red-eyes detracted from this photo. Then I realized it was very appropriate.', '2002-08-01 10:46:00.000000', NULL, 1),
(96455, 3854, 875, '<td valign="top">Clever - the red eye is perfect!  I think this might have worked better as a vertical photo instead of a horizontal one.  It would remove move of the distracting background.</td>', 'Clever - the red eye is perfect!  I think this might have worked better as a vertical photo instead of a horizontal one.  It would remove move of the distracting background.', '2002-08-01 23:59:00.000000', NULL, 1),
(96456, 3854, 2370, '<td valign="top">red eye effect on purpose?</td>', 'red eye effect on purpose?', '2002-08-02 01:39:00.000000', NULL, 1),
(96457, 3854, 1882, '<td valign="top">Eeek!  those red eyes!</td>', 'Eeek!  those red eyes!', '2002-08-02 09:17:00.000000', NULL, 1),
(96458, 3854, 811, '<td valign="top">Nice looking young man.  Almost looks too young to be involved with corporations, though.  I like the color and the focus, and how you got his skin tone ot look right.  Something about how he is framed is throwing me off though.  Maybe if he were turned slightly to his right, it would feel more balanced.  Was the red eye intentional?  If so, should''ve called it "evil corporate takeover." :-)</td>', 'Nice looking young man.  Almost looks too young to be involved with corporations, though.  I like the color and the focus, and how you got his skin tone ot look right.  Something about how he is framed is throwing me off though.  Maybe if he were turned slightly to his right, it would feel more balanced.  Was the red eye intentional?  If so, should''ve called it "evil corporate takeover." :-)', '2002-08-02 17:50:00.000000', NULL, 1),
(96459, 3854, 2792, '<td valign="top">Good red eyes!  Evil looking! muhahahah!</td>', 'Good red eyes!  Evil looking! muhahahah!', '2002-08-02 22:32:00.000000', NULL, 1),
(96460, 3854, 2932, '<td valign="top">It may be an illusion, but the horizon seems ever so slightly unlevel.  A little more snap to the greedy outstretched fingers and this would be a ten from me.</td>', 'It may be an illusion, but the horizon seems ever so slightly unlevel.  A little more snap to the greedy outstretched fingers and this would be a ten from me.', '2002-08-03 02:15:00.000000', NULL, 1),
(96461, 3854, 2837, '<td valign="top">i am wondering if the redeye was intentional or accedental. It works for the photo as he has sort of an evil look. I bet people will score low though with such remarks as "ahh bad redeye" heh.</td>', 'i am wondering if the redeye was intentional or accedental. It works for the photo as he has sort of an evil look. I bet people will score low though with such remarks as "ahh bad redeye" heh.', '2002-08-04 04:03:00.000000', NULL, 1),
(96462, 3854, 2023, '<td valign="top">Would have rated it much higher if not for the red eye.  <br/>Tell your subjects not to look directly at the lens.</td>', 'Would have rated it much higher if not for the red eye.  Tell your subjects not to look directly at the lens.', '2002-08-04 15:02:00.000000', NULL, 1),
(96463, 3854, 2719, '<td valign="top">Evil red eyes!</td>', 'Evil red eyes!', '2002-08-04 18:23:00.000000', NULL, 1),
(96464, 3855, 221, '<td valign="top">Does this really apply to the challenge?</td>', 'Does this really apply to the challenge?', '2002-07-29 01:22:00.000000', NULL, 1),
(96465, 3855, 772, '<td valign="top">this is a neat photo with the sun flare in it reflecting from the building.  the building in the upper right corner creates a bit of a distraction for me though.. - jmsetzler</td>', 'this is a neat photo with the sun flare in it reflecting from the building.  the building in the upper right corner creates a bit of a distraction for me though.. - jmsetzler', '2002-07-29 08:02:00.000000', NULL, 1),
(96466, 3855, 2752, '<td valign="top">nice design...the shining light great</td>', 'nice design...the shining light great', '2002-07-29 18:13:00.000000', NULL, 1),
(96467, 3855, 2158, '<td valign="top">I like the composition, but I can''t help feeling this would have worked better at a different time of day, when the lighting wasn''t so harsh.</td>', 'I like the composition, but I can''t help feeling this would have worked better at a different time of day, when the lighting wasn''t so harsh.', '2002-07-29 20:38:00.000000', NULL, 1),
(96468, 3855, 2798, '<td valign="top">This reflection fooled your camera''s exposure settings a little. Everything else looks a little dark.  You can barely see the flags in the foreground. Good use of title to explain away what was probably an accidental shot.</td>', 'This reflection fooled your camera''s exposure settings a little. Everything else looks a little dark.  You can barely see the flags in the foreground. Good use of title to explain away what was probably an accidental shot.', '2002-07-30 09:31:00.000000', NULL, 1),
(96469, 3855, 2928, '<td valign="top">Just love the drama in this picture; you can almost see Jones from accounts passing the 15th floor I like this picture a lot and I''m going to score it high because it carries the essence of the challenge really well.  It''s not busy, and the central feeling of mass and scale is breathtakingly superb. Ooops  am I going a bit over the top here (no way)  - One tiny, meagre fault  shame you caught the edge of the other building  still gets a 10  good luck with a great picture</td>', 'Just love the drama in this picture; you can almost see Jones from accounts passing the 15th floor I like this picture a lot and I''m going to score it high because it carries the essence of the challenge really well.  It''s not busy, and the central feeling of mass and scale is breathtakingly superb. Ooops  am I going a bit over the top here (no way)  - One tiny, meagre fault  shame you caught the edge of the other building  still gets a 10  good luck with a great picture', '2002-07-30 10:13:00.000000', NULL, 1),
(96470, 3855, 2278, '<td valign="top">I like the idea of the photo - just would like to be able to make out the details on the flags.  I think they might have added a cool shot of color.  (and shining only has 1 "n" :) )</td>', 'I like the idea of the photo - just would like to be able to make out the details on the flags.  I think they might have added a cool shot of color.  (and shining only has 1 "n" :) )', '2002-07-30 21:54:00.000000', NULL, 1),
(96471, 3855, 3014, '<td valign="top">This is a great example of a good photo with a title that really works.</td>', 'This is a great example of a good photo with a title that really works.', '2002-07-31 02:39:00.000000', NULL, 1),
(96472, 3855, 2146, '<td valign="top">i like this</td>', 'i like this', '2002-07-31 07:52:00.000000', NULL, 1),
(96473, 3855, 1019, '<td valign="top">good study of height in a building--it really soars</td>', 'good study of height in a building--it really soars', '2002-07-31 15:44:00.000000', NULL, 1),
(96474, 3855, 637, '<td valign="top">Can''t quite get comfortable with the lighting in this image. 4 sjgleah</td>', 'Can''t quite get comfortable with the lighting in this image. 4 sjgleah', '2002-08-01 06:44:00.000000', NULL, 1),
(96475, 3855, 1005, '<td valign="top">Nice shot.  I like the thought of the sun flare as the "shining star".  VERY minor nit:  Executive level employees are usually at the top of the building.  Maybe this should be a middle level manager that is outstanding. (kind of a joke)  The problem with your sun flare on the building is, it reflected inside the lens to create a green sun blotch above the building in the foreground.  The flags in the very front of your foregrounds are barely invisible, and probably not wanted or needed.  I started you with a 7, tried to talk myself up to an 8, but failed, still a 7.  Swash</td>', 'Nice shot.  I like the thought of the sun flare as the "shining star".  VERY minor nit:  Executive level employees are usually at the top of the building.  Maybe this should be a middle level manager that is outstanding. (kind of a joke)  The problem with your sun flare on the building is, it reflected inside the lens to create a green sun blotch above the building in the foreground.  The flags in the very front of your foregrounds are barely invisible, and probably not wanted or needed.  I started you with a 7, tried to talk myself up to an 8, but failed, still a 7.  Swash', '2002-08-01 19:50:00.000000', NULL, 1),
