(96512, 3859, 1280, '<td valign="top">Nice, tightly cropped, clear, and I''m sure many can relate to it.  Met the challenge.</td>', 'Nice, tightly cropped, clear, and I''m sure many can relate to it.  Met the challenge.', '2002-07-31 22:07:00.000000', NULL, 1),
(96513, 3859, 875, '<td valign="top">Nice framing and color, but I''d like to see a little more dramatic lighting.</td>', 'Nice framing and color, but I''d like to see a little more dramatic lighting.', '2002-08-01 18:14:00.000000', NULL, 1),
(96514, 3859, 472, '<td valign="top">I feel bad for the person in this watching their stock price go down and having to take aspirin.  Good job of conveying that emotion.  Nice colors in the shot.  Good framing.  mag99</td>', 'I feel bad for the person in this watching their stock price go down and having to take aspirin.  Good job of conveying that emotion.  Nice colors in the shot.  Good framing.  mag99', '2002-08-01 23:31:00.000000', NULL, 1),
