(96568, 3865, 117, '<td valign="top">nice flip flop good shot</td>', 'nice flip flop good shot', '2002-07-29 19:30:00.000000', NULL, 1),
(96569, 3865, 2983, '<td valign="top">The way the reflection is working is confusing, and it might be due to the use of black&amp;white.  A soft flash-fill would have helped add detail to the customers across the center of the picture.  Otherwise an interesting picture.</td>', 'The way the reflection is working is confusing, and it might be due to the use of black&white.  A soft flash-fill would have helped add detail to the customers across the center of the picture.  Otherwise an interesting picture.', '2002-07-29 19:39:00.000000', NULL, 1),
(96570, 3865, 1667, '<td valign="top">McDonalds fries and a Coke.  You are right!  There are 3 or 4 McDonalds surrounding the Duomo in Milan.  It''s really strange.</td>', 'McDonalds fries and a Coke.  You are right!  There are 3 or 4 McDonalds surrounding the Duomo in Milan.  It''s really strange.', '2002-07-29 23:12:00.000000', NULL, 1),
(96571, 3865, 2, '<td valign="top">I love the sharp contrasts of color in this shot.  The girl blurred on the left is a little unfortunate, since everything else in this picture is so crisp.  Nice submission.</td>', 'I love the sharp contrasts of color in this shot.  The girl blurred on the left is a little unfortunate, since everything else in this picture is so crisp.  Nice submission.', '2002-07-30 01:36:00.000000', NULL, 1),
(96572, 3865, 2278, '<td valign="top">This is my favorite so far - what a great Mickey D''s!</td>', 'This is my favorite so far - what a great Mickey D''s!', '2002-07-30 01:44:00.000000', NULL, 1),
(96573, 3865, 2791, '<td valign="top">nice reflection!!! :)</td>', 'nice reflection!!! :)', '2002-07-30 06:53:00.000000', NULL, 1),
(96574, 3865, 441, '<td valign="top">I''d have thought this shot would have been better bursting with colour!</td>', 'I''d have thought this shot would have been better bursting with colour!', '2002-07-30 08:47:00.000000', NULL, 1),
(96575, 3865, 2928, '<td valign="top">I just like it  a lot</td>', 'I just like it  a lot', '2002-07-30 12:42:00.000000', NULL, 1),
(96576, 3865, 772, '<td valign="top">this is a very interesting image.. i love the reflection.  My only issue is that McDonalds, in my own mind, is a bright and cheery place.  The darkness in this image is intriguing, but I''m not sure if it works well for me overall... - jmsetzler</td>', 'this is a very interesting image.. i love the reflection.  My only issue is that McDonalds, in my own mind, is a bright and cheery place.  The darkness in this image is intriguing, but I''m not sure if it works well for me overall... - jmsetzler', '2002-07-30 14:48:00.000000', NULL, 1),
(96577, 3865, 2238, '<td valign="top">I can''t work out what''s wrong with this picture but I like it all the same,</td>', 'I can''t work out what''s wrong with this picture but I like it all the same,', '2002-07-30 17:09:00.000000', NULL, 1),
(96578, 3865, 2481, '<td valign="top">not sure about the connection here.  nice black and white photo though</td>', 'not sure about the connection here.  nice black and white photo though', '2002-07-30 17:50:00.000000', NULL, 1),
