(96580, 3865, 2109, '<td valign="top">nice!  I''m interested in seeing this in color -7</td>', 'nice!  I''m interested in seeing this in color -7', '2002-07-30 22:15:00.000000', NULL, 1),
(96581, 3865, 3014, '<td valign="top">Nice composition with the reflection. The metal walls look even more start and cold with everything else in black and white.</td>', 'Nice composition with the reflection. The metal walls look even more start and cold with everything else in black and white.', '2002-07-31 02:35:00.000000', NULL, 1),
(96582, 3865, 2858, '<td valign="top">Love the lighting in this. It''s intriguing because of the reflaction. Works well as an advert rather than a statement about the corporate world. Still, top ten surely.</td>', 'Love the lighting in this. It''s intriguing because of the reflaction. Works well as an advert rather than a statement about the corporate world. Still, top ten surely.', '2002-07-31 06:57:00.000000', NULL, 1),
(96583, 3865, 133, '<td valign="top">A super black &amp; white photograph!</td>', 'A super black & white photograph!', '2002-07-31 08:41:00.000000', NULL, 1),
(96584, 3865, 472, '<td valign="top">definitely  true.  <br/>while you got the sign to pop, the people are a bit dark .. work wiht your curves a bit more...</td>', 'definitely  true.  while you got the sign to pop, the people are a bit dark .. work wiht your curves a bit more...', '2002-07-31 12:12:00.000000', NULL, 1),
(96585, 3865, 2261, '<td valign="top">A good shot but I just don''t like the reflection of the logo.  The b/w works really well though.</td>', 'A good shot but I just don''t like the reflection of the logo.  The b/w works really well though.', '2002-07-31 13:48:00.000000', NULL, 1),
(96586, 3865, 121, '<td valign="top">Nice composition. Blurring shows some of the hustle about the place.</td>', 'Nice composition. Blurring shows some of the hustle about the place.', '2002-07-31 17:41:00.000000', NULL, 1),
(96587, 3865, 2251, '<td valign="top">Corporate Deathburger, Ronald McDonald. To learn more about the detramental effects of capitalism and statism, go to www.infoshop.org<br/>-Ben</td>', 'Corporate Deathburger, Ronald McDonald. To learn more about the detramental effects of capitalism and statism, go to www.infoshop.org-Ben', '2002-07-31 19:14:00.000000', NULL, 1),
