(96589, 3865, 1944, '<td valign="top">Interesting angle. I like the reflection effect.</td>', 'Interesting angle. I like the reflection effect.', '2002-08-01 00:10:00.000000', NULL, 1),
(96590, 3865, 2456, '<td valign="top">Really like the picture. Nice capture of the challenge. Like the reflection and the mix of people. Looks kind of retro to me. Very nice. Daniellita</td>', 'Really like the picture. Nice capture of the challenge. Like the reflection and the mix of people. Looks kind of retro to me. Very nice. Daniellita', '2002-08-02 13:02:00.000000', NULL, 1),
