(96597, 3867, 2, '<td valign="top">The title''s really stretching it, so I don''t think you met the ''corporate'' part very well.  I _love_ the colors, though, and you''ve chosen an awesome angle.</td>', 'The title''s really stretching it, so I don''t think you met the ''corporate'' part very well.  I _love_ the colors, though, and you''ve chosen an awesome angle.', '2002-07-29 01:39:00.000000', NULL, 1),
(96598, 3867, 772, '<td valign="top">interesting photo, but it doesn''t say ''corporate world'' without the title... - jmsetzler</td>', 'interesting photo, but it doesn''t say ''corporate world'' without the title... - jmsetzler', '2002-07-29 02:10:00.000000', NULL, 1),
(96599, 3867, 1054, '<td valign="top">Nice shot, good connection to the theme. -ClubJuggle</td>', 'Nice shot, good connection to the theme. -ClubJuggle', '2002-07-29 02:59:00.000000', NULL, 1),
(96600, 3867, 2798, '<td valign="top">Good composition but everything looks a little red - white balance issue?</td>', 'Good composition but everything looks a little red - white balance issue?', '2002-07-29 09:28:00.000000', NULL, 1),
