(96602, 3867, 2000, '<td valign="top">Yeah, maybe.  But it''s a bit of a stretch to make it fit the challenge.</td>', 'Yeah, maybe.  But it''s a bit of a stretch to make it fit the challenge.', '2002-07-29 14:54:00.000000', NULL, 1),
(96603, 3867, 2553, '<td valign="top">Sorry, nothing about this shot makes me think "Corporate" other than the title.  lhall</td>', 'Sorry, nothing about this shot makes me think "Corporate" other than the title.  lhall', '2002-07-29 14:55:00.000000', NULL, 1),
(96604, 3867, 2752, '<td valign="top">good choice for the theme .  Composition is good and nice lighting</td>', 'good choice for the theme .  Composition is good and nice lighting', '2002-07-29 16:35:00.000000', NULL, 1),
(96605, 3867, 2983, '<td valign="top">I find the background mess to be distracting, especially the conduit and the junction box.  A good idea, but the elements of the photo you can''t really control are hurting it.</td>', 'I find the background mess to be distracting, especially the conduit and the junction box.  A good idea, but the elements of the photo you can''t really control are hurting it.', '2002-07-29 17:17:00.000000', NULL, 1),
(96606, 3867, 2586, '<td valign="top">Ad for theme parks? Corporations are not dinosaurs by any stretch of the imagination. So, I find your title and presentation stretching.</td>', 'Ad for theme parks? Corporations are not dinosaurs by any stretch of the imagination. So, I find your title and presentation stretching.', '2002-07-29 17:23:00.000000', NULL, 1),
(96607, 3867, 1175, '<td valign="top">Jurassic Park 2 sucked but they redeamed themselves with 3.... sort of.  Background is distracting.  My first suggestion would be to use a shallower depth of focus to isolate the dinosaur from the roof but then you might loose the sign on the left.</td>', 'Jurassic Park 2 sucked but they redeamed themselves with 3.... sort of.  Background is distracting.  My first suggestion would be to use a shallower depth of focus to isolate the dinosaur from the roof but then you might loose the sign on the left.', '2002-07-30 10:56:00.000000', NULL, 1),
(96608, 3867, 811, '<td valign="top">Scary.  That movie gave me nightmares. :-)  Would it have been possible to shoot looking straight into his mouth?  karmat</td>', 'Scary.  That movie gave me nightmares. :-)  Would it have been possible to shoot looking straight into his mouth?  karmat', '2002-07-30 17:41:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(96609, 3867, 2350, '<td valign="top">He''s special.  Certainly is a giant, but extinct.  I got it.</td>', 'He''s special.  Certainly is a giant, but extinct.  I got it.', '2002-07-30 21:17:00.000000', NULL, 1),
(96610, 3867, 2251, '<td valign="top">don''t let the blood thirsty bastards get away with their archaic ideas of hierarchial social relationships. To learn more about the detramental effects of capitalism and statism, go to www.infoshop.org<br/>-Ben</td>', 'don''t let the blood thirsty bastards get away with their archaic ideas of hierarchial social relationships. To learn more about the detramental effects of capitalism and statism, go to www.infoshop.org-Ben', '2002-07-31 18:50:00.000000', NULL, 1),
(96611, 3867, 637, '<td valign="top">A little too contrived for me 3 sjgleah</td>', 'A little too contrived for me 3 sjgleah', '2002-08-01 06:30:00.000000', NULL, 1),
(96612, 3867, 2221, '<td valign="top">nice lighting. i would have used less DOF to blur the background a little more. it distracts from your subject (especially the red letters).</td>', 'nice lighting. i would have used less DOF to blur the background a little more. it distracts from your subject (especially the red letters).', '2002-08-02 22:56:00.000000', NULL, 1),
(96613, 3867, 509, '<td valign="top">Strange color cast on an otherwise very good shot.  Did you try different white balances?  I would have preferred a cooler (as in more blue) one, so that there would be less of a red tint on the T-Rex</td>', 'Strange color cast on an otherwise very good shot.  Did you try different white balances?  I would have preferred a cooler (as in more blue) one, so that there would be less of a red tint on the T-Rex', '2002-08-04 19:24:00.000000', NULL, 1),
(96614, 3869, 92, '<td valign="top">PERFECT ! Not much else I can say. You nailed it:) = 10 Shiiiizzzam</td>', 'PERFECT ! Not much else I can say. You nailed it:) = 10 Shiiiizzzam', '2002-07-29 03:14:00.000000', NULL, 1),
(96615, 3869, 2553, '<td valign="top">Certainly projects one of the things I think of when I consider the "Corporate World".  However, the overall image doesn''t really engage my interest.</td>', 'Certainly projects one of the things I think of when I consider the "Corporate World".  However, the overall image doesn''t really engage my interest.', '2002-07-29 06:30:00.000000', NULL, 1),
(96616, 3869, 671, '<td valign="top">Hmm.  This looks like it''s too close to home.  It didn''t happen to you, I hope?</td>', 'Hmm.  This looks like it''s too close to home.  It didn''t happen to you, I hope?', '2002-07-29 10:33:00.000000', NULL, 1),
(96617, 3869, 2752, '<td valign="top">good perspective visually and actually</td>', 'good perspective visually and actually', '2002-07-29 11:56:00.000000', NULL, 1),
(96618, 3869, 2352, '<td valign="top">I like it!  Nice clean shot.  Well lit with color standouts, and tells a story...</td>', 'I like it!  Nice clean shot.  Well lit with color standouts, and tells a story...', '2002-07-29 22:52:00.000000', NULL, 1),
(96619, 3869, 917, '<td valign="top">Its a good subject, but needs some added elements to drive things home. Perhaps the red hands could have an ''I love you daddy'' in childs writing. Maybe replace the small framed pictures with a family portrait at A4 size just to make it clear that there is a family in trouble out there today. You could add an unfinised todo list. The framed circuit board needs to be a part of the bit and peices of the life thats ended rather than the focus. A newspaper with awful headlines could help too. Try a vertical frame to eliminate the cubicle door and show the other empty cubicles. I like the missing PC. Im afraid this looks a bit rushed in some ways. Erm, was someone standing over you whilst you did this? I get the feeling this may have been a real sacking.</td>', 'Its a good subject, but needs some added elements to drive things home. Perhaps the red hands could have an ''I love you daddy'' in childs writing. Maybe replace the small framed pictures with a family portrait at A4 size just to make it clear that there is a family in trouble out there today. You could add an unfinised todo list. The framed circuit board needs to be a part of the bit and peices of the life thats ended rather than the focus. A newspaper with awful headlines could help too. Try a vertical frame to eliminate the cubicle door and show the other empty cubicles. I like the missing PC. Im afraid this looks a bit rushed in some ways. Erm, was someone standing over you whilst you did this? I get the feeling this may have been a real sacking.', '2002-07-30 12:49:00.000000', NULL, 1),
(96620, 3869, 835, '<td valign="top">I really like how clear everything is</td>', 'I really like how clear everything is', '2002-07-30 18:31:00.000000', NULL, 1),
(96621, 3869, 210, '<td valign="top">Almost making me wonder if this is real or not...</td>', 'Almost making me wonder if this is real or not...', '2002-07-30 18:40:00.000000', NULL, 1),
(96622, 3869, 2109, '<td valign="top">life sucking cubicles</td>', 'life sucking cubicles', '2002-07-30 22:38:00.000000', NULL, 1),
(96623, 3869, 3014, '<td valign="top">Stark. I wonder if some color manipulation would make it even more stark?</td>', 'Stark. I wonder if some color manipulation would make it even more stark?', '2002-07-30 23:38:00.000000', NULL, 1),
(96624, 3869, 1944, '<td valign="top">One of the better interportations of the theme. Nice technicaly also.</td>', 'One of the better interportations of the theme. Nice technicaly also.', '2002-07-31 00:14:00.000000', NULL, 1),
(96625, 3869, 737, '<td valign="top">Composition - very good<br/>Technical Aspects - very good<br/>Meets Challenge -yes<br/>Visual Impact / Originality - high<br/></td>', 'Composition - very goodTechnical Aspects - very goodMeets Challenge -yesVisual Impact / Originality - high', '2002-07-31 00:28:00.000000', NULL, 1),
(96626, 3869, 1169, '<td valign="top">yeah, like me</td>', 'yeah, like me', '2002-07-31 04:29:00.000000', NULL, 1),
