(96629, 3869, 121, '<td valign="top">Not suprised he got laid off if he wore those ties to work. WOW. I thought this type of office only existed in cartoons and laboratories (for the mice). Well taken, nice idea, excellent lighting and exposure. Hey you have the same phone as me!</td>', 'Not suprised he got laid off if he wore those ties to work. WOW. I thought this type of office only existed in cartoons and laboratories (for the mice). Well taken, nice idea, excellent lighting and exposure. Hey you have the same phone as me!', '2002-07-31 17:38:00.000000', NULL, 1),
(96630, 3869, 1280, '<td valign="top">I''ve never had a desk of mine look so neat!</td>', 'I''ve never had a desk of mine look so neat!', '2002-07-31 21:08:00.000000', NULL, 1),
(96631, 3869, 637, '<td valign="top">too close to home ; but seriously, the sparseness may be what you''re trying to convey, but it leaves me wanting something else from this image. 5 sjgleah<br/></td>', 'too close to home ; but seriously, the sparseness may be what you''re trying to convey, but it leaves me wanting something else from this image. 5 sjgleah', '2002-08-01 06:48:00.000000', NULL, 1),
(96632, 3870, 2638, '<td valign="top">great imagination</td>', 'great imagination', '2002-07-29 05:07:00.000000', NULL, 1),
(96633, 3870, 917, '<td valign="top">Perhaps some ingredients need to be in the background. Take a look at the photos in a magazines recipe slot and try to replicate thier style, only with books instead of carrots, then the meaning will come acroos more clearly.</td>', 'Perhaps some ingredients need to be in the background. Take a look at the photos in a magazines recipe slot and try to replicate thier style, only with books instead of carrots, then the meaning will come acroos more clearly.', '2002-07-29 09:35:00.000000', NULL, 1),
(96634, 3870, 671, '<td valign="top">LOL! Good idea.</td>', 'LOL! Good idea.', '2002-07-29 10:30:00.000000', NULL, 1),
(96635, 3870, 1024, '<td valign="top">Funny play on words.  I wish the books being cooked were recognizable.</td>', 'Funny play on words.  I wish the books being cooked were recognizable.', '2002-07-29 12:15:00.000000', NULL, 1),
