(96982, 3892, 801, '<td valign="top">Is Starbucks stimulating anything or the next financial scandal?</td>', 'Is Starbucks stimulating anything or the next financial scandal?', '2002-07-29 09:52:00.000000', NULL, 1),
(96983, 3892, 2000, '<td valign="top">Another commercial.  I can''t compare to other pics, but Starbucks isn''t much for the corporate world.</td>', 'Another commercial.  I can''t compare to other pics, but Starbucks isn''t much for the corporate world.', '2002-07-29 15:04:00.000000', NULL, 1),
(96984, 3892, 2983, '<td valign="top">Nothing particularly interesting in the subject matter, other than the standard jab at the Starbucks'' stereotypical mentality.  Technically, the photo seems crooked (slightly tilted to the left) and under-exposed, perhaps due to time of day.  More planning could''ve helped this.</td>', 'Nothing particularly interesting in the subject matter, other than the standard jab at the Starbucks'' stereotypical mentality.  Technically, the photo seems crooked (slightly tilted to the left) and under-exposed, perhaps due to time of day.  More planning could''ve helped this.', '2002-07-29 19:29:00.000000', NULL, 1),
(96985, 3892, 1569, '<td valign="top">A brighter more sunny day would have helped,also stepping around that plant in the lower right.</td>', 'A brighter more sunny day would have helped,also stepping around that plant in the lower right.', '2002-07-29 21:50:00.000000', NULL, 1),
(96986, 3892, 2798, '<td valign="top">A very conventional shot. The idea is good but you could have found an angle that would have made it more dramatic. It''s also a little under exposed.</td>', 'A very conventional shot. The idea is good but you could have found an angle that would have made it more dramatic. It''s also a little under exposed.', '2002-07-30 08:29:00.000000', NULL, 1),
(96987, 3892, 2481, '<td valign="top">line of tree is too close to line of window and line of umbrella - too much going on in photo to see any focal point for composition; starbucks might like it though...</td>', 'line of tree is too close to line of window and line of umbrella - too much going on in photo to see any focal point for composition; starbucks might like it though...', '2002-07-30 18:03:00.000000', NULL, 1),
(96988, 3892, 1877, '<td valign="top">Starbucks have DRIVE THRUs?? too bad there aren''t many people around .. 6</td>', 'Starbucks have DRIVE THRUs?? too bad there aren''t many people around .. 6', '2002-07-30 20:05:00.000000', NULL, 1),
(96989, 3892, 2858, '<td valign="top">This is a good advert.</td>', 'This is a good advert.', '2002-07-30 20:12:00.000000', NULL, 1),
(96990, 3892, 2928, '<td valign="top">I''m sorry I can''t be a little more positive, but I can''t say that I like the composition.  In many respects it''s a sharp, clear image, but it lacks character and looks rushed</td>', 'I''m sorry I can''t be a little more positive, but I can''t say that I like the composition.  In many respects it''s a sharp, clear image, but it lacks character and looks rushed', '2002-07-31 10:08:00.000000', NULL, 1),
(96991, 3892, 2352, '<td valign="top">I like the title!  Nice clean picture.</td>', 'I like the title!  Nice clean picture.', '2002-07-31 22:02:00.000000', NULL, 1),
(96992, 3892, 1944, '<td valign="top">I wonder what percentage of the corporate world''s business is done inside these doors:)</td>', 'I wonder what percentage of the corporate world''s business is done inside these doors:)', '2002-08-01 00:12:00.000000', NULL, 1),
(96993, 3892, 637, '<td valign="top">Concept is valid; meets the challenge; image is quite boring and uncaptivating.  Could use better sky, perhaps a customer or two; perhaps centering in on the menu. 4 sjgleah</td>', 'Concept is valid; meets the challenge; image is quite boring and uncaptivating.  Could use better sky, perhaps a customer or two; perhaps centering in on the menu. 4 sjgleah', '2002-08-01 06:43:00.000000', NULL, 1),
(96994, 3892, 1005, '<td valign="top">Tom, this is certainly not your best shot.  Couldn''t you do something with your computer, etc, sort of a travelling businessman thing?  Crop the greenhouse, lose more of the grey sky, would have been a little more effective.  You might want to start going for your challenge shot a little earlier in the week (as opposed to Sunday evening around 8 PM.)  7 Swash</td>', 'Tom, this is certainly not your best shot.  Couldn''t you do something with your computer, etc, sort of a travelling businessman thing?  Crop the greenhouse, lose more of the grey sky, would have been a little more effective.  You might want to start going for your challenge shot a little earlier in the week (as opposed to Sunday evening around 8 PM.)  7 Swash', '2002-08-01 20:10:00.000000', NULL, 1),
(96995, 3892, 2932, '<td valign="top">my favorite corporate icon!</td>', 'my favorite corporate icon!', '2002-08-03 02:08:00.000000', NULL, 1),
(96996, 3894, 772, '<td valign="top">interesting photo, but it doesn''t say ''corporate world'' without the title... - jmsetzler</td>', 'interesting photo, but it doesn''t say ''corporate world'' without the title... - jmsetzler', '2002-07-29 02:20:00.000000', NULL, 1),
(96997, 3894, 2798, '<td valign="top">Great depth of field shot. But is it really eckerds that is placing greed and profit over health?</td>', 'Great depth of field shot. But is it really eckerds that is placing greed and profit over health?', '2002-07-29 09:15:00.000000', NULL, 1),
(96998, 3894, 157, '<td valign="top">you should come live in Canada...good ol'' free health care :) - oh yeah..photography comments...right: I love the DOF on this one.</td>', 'you should come live in Canada...good ol'' free health care :) - oh yeah..photography comments...right: I love the DOF on this one.', '2002-07-29 10:21:00.000000', NULL, 1),
(96999, 3894, 1856, '<td valign="top">Intriguing and unique photo.  I think to emphasize the ''corp'' aspect of this you would place the pills in the foreground of the picture as to show the lilly, merck, etc labels on the pills.  I do like the idea.  7  Lisa<br/><br/>If this sounds snooty it''s because I''ve been goaded into leaving the words great and nice out of my critiques and to use more colorful and accurate vocabulary.  Sorry to make you the guinea pig. ;)</td>', 'Intriguing and unique photo.  I think to emphasize the ''corp'' aspect of this you would place the pills in the foreground of the picture as to show the lilly, merck, etc labels on the pills.  I do like the idea.  7  LisaIf this sounds snooty it''s because I''ve been goaded into leaving the words great and nice out of my critiques and to use more colorful and accurate vocabulary.  Sorry to make you the guinea pig. ;)', '2002-07-29 16:30:00.000000', NULL, 1),
(97000, 3894, 2983, '<td valign="top">You may be strutching the theme a bit on this one, but the photo itself is technically good.  The only problem for me is it seems slightly under-exposed.</td>', 'You may be strutching the theme a bit on this one, but the photo itself is technically good.  The only problem for me is it seems slightly under-exposed.', '2002-07-29 19:31:00.000000', NULL, 1),
(97001, 3894, 2928, '<td valign="top">This picture, like it''s content, is very clinical.  If I look at the technical nature of the photo, I can''t fault it, it''s a very good picture, and, it tells a story  but is it the right story?   I have to score it quite low, because in my view, it doesn''t meet the "Corporate" challenge too well.  I like it, don''t get me wrong, if it were less medical, and more corporate in content I would have scored very high</td>', 'This picture, like it''s content, is very clinical.  If I look at the technical nature of the photo, I can''t fault it, it''s a very good picture, and, it tells a story  but is it the right story?   I have to score it quite low, because in my view, it doesn''t meet the "Corporate" challenge too well.  I like it, don''t get me wrong, if it were less medical, and more corporate in content I would have scored very high', '2002-07-30 11:04:00.000000', NULL, 1),
(97002, 3894, 2352, '<td valign="top">It just doesn`t tell me a story.  I need more to look at...</td>', 'It just doesn`t tell me a story.  I need more to look at...', '2002-07-30 21:40:00.000000', NULL, 1),
(97003, 3894, 2109, '<td valign="top">Technically, its an excellent photograph with nice depth of field.  However, it does not convey the image that the title suggests.  The challenge is for the photograph itself, not the title.</td>', 'Technically, its an excellent photograph with nice depth of field.  However, it does not convey the image that the title suggests.  The challenge is for the photograph itself, not the title.', '2002-07-30 22:07:00.000000', NULL, 1),
(97004, 3894, 3014, '<td valign="top">Put some coins in that bottle, or use a dollar for the label.</td>', 'Put some coins in that bottle, or use a dollar for the label.', '2002-07-30 23:31:00.000000', NULL, 1),
(97005, 3894, 1054, '<td valign="top">This is an excellent photograph but unfortunately it only peripherally meets the challenge.  I see where you were going and could have conveyed the idea in your title very effectively with some different takes on it. -ClubJuggle</td>', 'This is an excellent photograph but unfortunately it only peripherally meets the challenge.  I see where you were going and could have conveyed the idea in your title very effectively with some different takes on it. -ClubJuggle', '2002-07-31 00:38:00.000000', NULL, 1),
(97006, 3894, 1169, '<td valign="top">true</td>', 'true', '2002-07-31 04:26:00.000000', NULL, 1),
(97007, 3894, 133, '<td valign="top">An interesting choice of topics and a nice close up.  I might have tried different angles on this one or focused on the pills instead of the bottle.</td>', 'An interesting choice of topics and a nice close up.  I might have tried different angles on this one or focused on the pills instead of the bottle.', '2002-07-31 09:01:00.000000', NULL, 1),
(97008, 3894, 637, '<td valign="top">A little too much editorial for my taste... your image doesn''t show greed/profit either.  3 sjgleah</td>', 'A little too much editorial for my taste... your image doesn''t show greed/profit either.  3 sjgleah', '2002-08-01 06:35:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(97009, 3894, 1005, '<td valign="top">Soo right!  Nice title/pic match.  Unusual angle of attack, usually this type shot is done from the opposite side (pills first).  Somehow, I like this.  I can see why the other view is used most often, it promotes the pretty pills.  You did well to promote the drug company instead.  You slipped up one notch, from 7 to 8.  Swash</td>', 'Soo right!  Nice title/pic match.  Unusual angle of attack, usually this type shot is done from the opposite side (pills first).  Somehow, I like this.  I can see why the other view is used most often, it promotes the pretty pills.  You did well to promote the drug company instead.  You slipped up one notch, from 7 to 8.  Swash', '2002-08-01 20:55:00.000000', NULL, 1),
(97010, 3894, 509, '<td valign="top">great depth of field</td>', 'great depth of field', '2002-08-04 19:33:00.000000', NULL, 1),
(97011, 3894, 173, '<td valign="top">TRUE STORY!!!!!!!!!</td>', 'TRUE STORY!!!!!!!!!', '2002-08-05 01:02:00.000000', NULL, 0),
(97023, 3896, 2452, '<td valign="top">Are you South African? This looks familiar - I ALMOST did the same!! Nice Shot - 9!</td>', 'Are you South African? This looks familiar - I ALMOST did the same!! Nice Shot - 9!', '2002-07-29 02:17:00.000000', NULL, 1),
(97024, 3896, 2000, '<td valign="top">The title is too necessary to undertand the picture.</td>', 'The title is too necessary to undertand the picture.', '2002-07-29 14:33:00.000000', NULL, 1),
