(97041, 3896, 509, '<td valign="top">I think I would have liked this better with the grass cropped out, very good nonetheless - 7</td>', 'I think I would have liked this better with the grass cropped out, very good nonetheless - 7', '2002-08-04 19:33:00.000000', NULL, 1),
