(97194, 3906, 737, '<td valign="top">Composition - good<br/>Technical Aspects -good<br/>Meets Challenge - yes<br/>Visual Impact / Originality - good<br/></td>', 'Composition - goodTechnical Aspects -goodMeets Challenge - yesVisual Impact / Originality - good', '2002-07-31 00:27:00.000000', NULL, 1),
