(97606, 3928, 2247, '<td valign="top">LOL!!!!!!!!!!!!!!  Very, VERY funny!!  Your pic of the letter seems to show what a number of corporations seem to consider "essential" ethical standard.</td>', 'LOL!!!!!!!!!!!!!!  Very, VERY funny!!  Your pic of the letter seems to show what a number of corporations seem to consider "essential" ethical standard.', '2002-08-04 22:56:00.000000', NULL, 1),
(97607, 3929, 2170, '<td valign="top">Of all of the "money down the drain" pictures, this is by far the best.</td>', 'Of all of the "money down the drain" pictures, this is by far the best.', '2002-07-29 01:15:00.000000', NULL, 1),
(97608, 3929, 2337, '<td valign="top">My first reaction was that the fork and knife should be facing the viewer... This lets the viewer off the hook by suggesting it is someone elses greed.  I like the play of light through the glass</td>', 'My first reaction was that the fork and knife should be facing the viewer... This lets the viewer off the hook by suggesting it is someone elses greed.  I like the play of light through the glass', '2002-07-29 02:37:00.000000', NULL, 1),
(97609, 3929, 1360, '<td valign="top">The odd light color is somewhat distracting; so is the shadows in the dollar bills.  This might look better with some even handed lighting, perhaps something to bring out some of the deep shadows inside the crumpled bills?</td>', 'The odd light color is somewhat distracting; so is the shadows in the dollar bills.  This might look better with some even handed lighting, perhaps something to bring out some of the deep shadows inside the crumpled bills?', '2002-07-29 04:56:00.000000', NULL, 1),
(97610, 3929, 2798, '<td valign="top">Great colours, contrast and concept. Perhaps a little too much contrast.</td>', 'Great colours, contrast and concept. Perhaps a little too much contrast.', '2002-07-29 09:30:00.000000', NULL, 1),
(97611, 3929, 2111, '<td valign="top">like it. color a bit off 6</td>', 'like it. color a bit off 6', '2002-07-29 10:32:00.000000', NULL, 1),
