INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(97620, 3929, 1202, '<td valign="top">Composition8<br/>Technical Aspects8<br/>Appeal6Interesting concept, but I don''t care for the ovetones of pink and blue.<br/>Difficulty6<br/>Rating7<br/>Autool</td>', 'Composition8Technical Aspects8Appeal6Interesting concept, but I don''t care for the ovetones of pink and blue.Difficulty6Rating7Autool', '2002-07-30 10:23:00.000000', NULL, 1),
(97621, 3929, 811, '<td valign="top">was the blue/purplish tint intentional?  kinda a neat effect.  Good idea, but I think the bowl should be further down in the picture.  Maybe crop the utensils and not the glass.  karmat</td>', 'was the blue/purplish tint intentional?  kinda a neat effect.  Good idea, but I think the bowl should be further down in the picture.  Maybe crop the utensils and not the glass.  karmat', '2002-07-30 17:17:00.000000', NULL, 1),
(97622, 3929, 2587, '<td valign="top">Great idea. The only thing that distracts me is the use of purple. I"m not sure how that fits in. I''d also either get rid of the glass or fill it with something that relates to the metaphor. Composition and light is good though.</td>', 'Great idea. The only thing that distracts me is the use of purple. I"m not sure how that fits in. I''d also either get rid of the glass or fill it with something that relates to the metaphor. Composition and light is good though.', '2002-07-30 17:26:00.000000', NULL, 1),
(97623, 3929, 2352, '<td valign="top">Clever play on words with a picture...  Colorful!</td>', 'Clever play on words with a picture...  Colorful!', '2002-07-30 21:42:00.000000', NULL, 1),
(97624, 3929, 1944, '<td valign="top">IMHO, it would have been a stronger picture with natural colors. Good composition and exposure though.</td>', 'IMHO, it would have been a stronger picture with natural colors. Good composition and exposure though.', '2002-07-31 02:00:00.000000', NULL, 1),
(97625, 3929, 2146, '<td valign="top">can I have seconds please?</td>', 'can I have seconds please?', '2002-07-31 07:42:00.000000', NULL, 1),
(97626, 3929, 2928, '<td valign="top">Witty idea, original and to the point Although, I''m not sure I like the lighting effects or understand their meaning.  The lighting (in my opinion) has generated overkill on a image that could easily stand on its own without it.</td>', 'Witty idea, original and to the point Although, I''m not sure I like the lighting effects or understand their meaning.  The lighting (in my opinion) has generated overkill on a image that could easily stand on its own without it.', '2002-07-31 10:24:00.000000', NULL, 1),
(97627, 3929, 2983, '<td valign="top">Color seems odd, like the green channel is low.  Good subject</td>', 'Color seems odd, like the green channel is low.  Good subject', '2002-07-31 12:43:00.000000', NULL, 1),
(97628, 3929, 1005, '<td valign="top">This is a really good idea!  I especially like the coin drink!  First, it does appear on the dark side on my monitor.  Next, I question your photo angle and cropping.  I would suggest taking this from the view of the eater.  Next, I would suggest not cropping the basic elements out of the shot.  (I''m so square, I like seeing the whole picture)  Lastly, the red glow?  Is that from a filter?  Kinda surreal, if that was what you were going for....Good job!  8 Swash</td>', 'This is a really good idea!  I especially like the coin drink!  First, it does appear on the dark side on my monitor.  Next, I question your photo angle and cropping.  I would suggest taking this from the view of the eater.  Next, I would suggest not cropping the basic elements out of the shot.  (I''m so square, I like seeing the whole picture)  Lastly, the red glow?  Is that from a filter?  Kinda surreal, if that was what you were going for....Good job!  8 Swash', '2002-07-31 14:37:00.000000', NULL, 1),
(97629, 3929, 121, '<td valign="top">Why are the knife and fork upside down? IMHO the colours look a bit odd, too much blue cast and generally a bit fuzzy.</td>', 'Why are the knife and fork upside down? IMHO the colours look a bit odd, too much blue cast and generally a bit fuzzy.', '2002-07-31 17:47:00.000000', NULL, 1),
(97630, 3929, 1280, '<td valign="top">Your picture has impact!  "BAM" as Emeril  might say. The coloring is sort of surreal, and is very fitting.  Something so basic as eating, is so familiar to all. So right off you identify with your audience. VERY GOOD!  Then as my eye wanders over the scene I am impacted with UGH!  Eating money....yuck!  So the photo effectively provoked  disdain. VERY GOOD!  Brilliant photo.  A little bitty thang that is distracting is the crease in the fabric but at least it''s on a nice diagonal... :-) Oh and technically...yeah...looks fine to me.  10 Gracious</td>', 'Your picture has impact!  "BAM" as Emeril  might say. The coloring is sort of surreal, and is very fitting.  Something so basic as eating, is so familiar to all. So right off you identify with your audience. VERY GOOD!  Then as my eye wanders over the scene I am impacted with UGH!  Eating money....yuck!  So the photo effectively provoked  disdain. VERY GOOD!  Brilliant photo.  A little bitty thang that is distracting is the crease in the fabric but at least it''s on a nice diagonal... :-) Oh and technically...yeah...looks fine to me.  10 Gracious', '2002-07-31 18:12:00.000000', NULL, 1),
(97631, 3929, 2123, '<td valign="top">The knife and fork are upside down..lol.  A little shadowing too, perhaps, but funny. :-)</td>', 'The knife and fork are upside down..lol.  A little shadowing too, perhaps, but funny. :-)', '2002-08-01 16:18:00.000000', NULL, 1),
(97632, 3929, 3073, '<td valign="top">I especialy lke the angle you took this picture from. Just a guess you''re left handed. If the knife were in the green salad it would say a whole other story however a spoon gives a since of greed. The best part this guy even needed the small change to wash it down (crook). Every asspect of this photo is well thought out. Love the colours. 10</td>', 'I especialy lke the angle you took this picture from. Just a guess you''re left handed. If the knife were in the green salad it would say a whole other story however a spoon gives a since of greed. The best part this guy even needed the small change to wash it down (crook). Every asspect of this photo is well thought out. Love the colours. 10', '2002-08-03 06:00:00.000000', NULL, 1),
(97633, 3929, 2370, '<td valign="top">the colour scheme looks werid in this photo, was it purposeful? there''s like too much purple in the picture.</td>', 'the colour scheme looks werid in this photo, was it purposeful? there''s like too much purple in the picture.', '2002-08-04 09:41:00.000000', NULL, 1),
