(97671, 3931, 806, '<td valign="top">One of my 10''s this week, Kim! Nice work!</td>', 'One of my 10''s this week, Kim! Nice work!', '2002-08-05 01:27:00.000000', NULL, 0),
(97672, 3931, 885, '<td valign="top">Yeah, there is no adam''s apple cause I had to use myself as the model, having no available male model at the time I had the idea for the picture.  Thanks to Macy''s for generously letting me ''borrow'' the clothing :-)</td>', 'Yeah, there is no adam''s apple cause I had to use myself as the model, having no available male model at the time I had the idea for the picture.  Thanks to Macy''s for generously letting me ''borrow'' the clothing :-)', '2002-08-05 10:17:00.000000', NULL, 0),
(97673, 3932, 2079, '<td valign="top">Actually, I gave him a 7 on that photo, I wonder how many people will take the time to figure out who''s photo it is? -  Shalom Brother</td>', 'Actually, I gave him a 7 on that photo, I wonder how many people will take the time to figure out who''s photo it is? -  Shalom Brother', '2002-07-29 02:16:00.000000', NULL, 1),
(97674, 3932, 92, '<td valign="top">Is she for hire? PERFECT photo = 10 Shiiizzzam</td>', 'Is she for hire? PERFECT photo = 10 Shiiizzzam', '2002-07-29 03:07:00.000000', NULL, 1),
(97675, 3932, 210, '<td valign="top">The picture fits into the criteria, but the title doesn''t.  What does DPC have to do with the corporate world?</td>', 'The picture fits into the criteria, but the title doesn''t.  What does DPC have to do with the corporate world?', '2002-07-29 04:14:00.000000', NULL, 1),
(97676, 3932, 2586, '<td valign="top">Manipulative. Suppose the monitor shows one of your earlier submissions. The woman does not look like she''s the owner of that office, probably your wife. Yes, it''s an office setting but that''s about the only relationship I see with the challenge. 5</td>', 'Manipulative. Suppose the monitor shows one of your earlier submissions. The woman does not look like she''s the owner of that office, probably your wife. Yes, it''s an office setting but that''s about the only relationship I see with the challenge. 5', '2002-07-29 05:34:00.000000', NULL, 1),
