(97809, 3941, 2000, '<td valign="top">This works.  A bull, the gate, and that office building behind plays well into the challenge.</td>', 'This works.  A bull, the gate, and that office building behind plays well into the challenge.', '2002-07-29 14:43:00.000000', NULL, 1),
(97810, 3941, 2586, '<td valign="top">Find the green leaves distracting. If you had gotten closer to the bull statue without losing the gate, it would have been more effective. But you might have lost the corporate building behind. Mmmm, tough.</td>', 'Find the green leaves distracting. If you had gotten closer to the bull statue without losing the gate, it would have been more effective. But you might have lost the corporate building behind. Mmmm, tough.', '2002-07-29 16:23:00.000000', NULL, 1),
(97811, 3941, 210, '<td valign="top">I really like the idea you were trying to capture.  Unfortunately it''s unfocused and kind of haphazard.  I think this would have been great if you had spent some more time on it.</td>', 'I really like the idea you were trying to capture.  Unfortunately it''s unfocused and kind of haphazard.  I think this would have been great if you had spent some more time on it.', '2002-07-29 16:51:00.000000', NULL, 1),
(97812, 3941, 117, '<td valign="top">you know I had that idea but I was going to use a cow next to a bush and say where is my bull, bush i like you image concept</td>', 'you know I had that idea but I was going to use a cow next to a bush and say where is my bull, bush i like you image concept', '2002-07-29 20:13:00.000000', NULL, 1),
(97813, 3941, 2352, '<td valign="top">Clever shot.  I think you need a tri pod...</td>', 'Clever shot.  I think you need a tri pod...', '2002-07-29 22:53:00.000000', NULL, 1),
(97814, 3941, 2278, '<td valign="top">If the bull is your primary subject, it should be better emphasized in the photo.  I''d like to see this as a landscape photo with the bull filling (maybe overfilling some) the frame so that I didn''t have to rely on the title.</td>', 'If the bull is your primary subject, it should be better emphasized in the photo.  I''d like to see this as a landscape photo with the bull filling (maybe overfilling some) the frame so that I didn''t have to rely on the title.', '2002-07-30 01:02:00.000000', NULL, 1),
(97815, 3941, 2798, '<td valign="top">Is this a picture of a tree or a bull? Good concept but I think the tree is too large and distracting.</td>', 'Is this a picture of a tree or a bull? Good concept but I think the tree is too large and distracting.', '2002-07-30 08:34:00.000000', NULL, 1),
(97816, 3941, 811, '<td valign="top">I think the bull needs to be a more important part of the picture.  He almost gets lost down there at the bottom. karmat</td>', 'I think the bull needs to be a more important part of the picture.  He almost gets lost down there at the bottom. karmat', '2002-07-30 17:39:00.000000', NULL, 1),
(97817, 3941, 1280, '<td valign="top">Title and picture correlate well.  I love the colors.  The out-of-focus foliage on the right serves as a frame but because it''s very light, it is distracting.  I''d like to see it toned down.  The whimsical touch here is the unearthly colored bull in the courtyard.   All that shiny glass up top depicts fragility to me.  My vision has never been the greates but this seems as if it could be a little crearer, but over all I like this photo.  Keep up the nice work!   7  Gracious</td>', 'Title and picture correlate well.  I love the colors.  The out-of-focus foliage on the right serves as a frame but because it''s very light, it is distracting.  I''d like to see it toned down.  The whimsical touch here is the unearthly colored bull in the courtyard.   All that shiny glass up top depicts fragility to me.  My vision has never been the greates but this seems as if it could be a little crearer, but over all I like this photo.  Keep up the nice work!   7  Gracious', '2002-07-31 17:44:00.000000', NULL, 1),
(97818, 3941, 2251, '<td valign="top">the market is bullshit. To learn more about the detramental effects of capitalism and statism, go to www.infoshop.org<br/>-Ben</td>', 'the market is bullshit. To learn more about the detramental effects of capitalism and statism, go to www.infoshop.org-Ben', '2002-07-31 19:24:00.000000', NULL, 1),
(97819, 3942, 1054, '<td valign="top">Nice idea.  I would have preferred to see this cropped (or shot) a little to the left though.  The water tower in the background takes away from the feeling of this being a corporate center.  Also, this would have allowed you to place the Ameritach building off-center per the rule of thirds. -ClubJuggle</td>', 'Nice idea.  I would have preferred to see this cropped (or shot) a little to the left though.  The water tower in the background takes away from the feeling of this being a corporate center.  Also, this would have allowed you to place the Ameritach building off-center per the rule of thirds. -ClubJuggle', '2002-07-29 02:57:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(97820, 3942, 2837, '<td valign="top">a little murky, could have been taken on a clearer day maybe, with more light out</td>', 'a little murky, could have been taken on a clearer day maybe, with more light out', '2002-07-29 04:37:00.000000', NULL, 1),
(97821, 3942, 671, '<td valign="top">The smog is a nice touch.</td>', 'The smog is a nice touch.', '2002-07-29 10:36:00.000000', NULL, 1),
(97822, 3942, 210, '<td valign="top">A bit of sharpening and leveling would have gone a long way for this picture.  Otherwise, it came out somewhat bland.</td>', 'A bit of sharpening and leveling would have gone a long way for this picture.  Otherwise, it came out somewhat bland.', '2002-07-29 16:52:00.000000', NULL, 1),
(97823, 3942, 2752, '<td valign="top">looks a little grainy on my screen ...good theme</td>', 'looks a little grainy on my screen ...good theme', '2002-07-29 18:24:00.000000', NULL, 1),
(97824, 3942, 2278, '<td valign="top">I think this photo would be really cool as a portrait orientation with only the Ameritech bldg filling the frame.</td>', 'I think this photo would be really cool as a portrait orientation with only the Ameritech bldg filling the frame.', '2002-07-30 01:46:00.000000', NULL, 1),
(97825, 3942, 2928, '<td valign="top">This is a great picture; it''s dramatic, romantic and not unlike a postcard.  But, I''m going to score quite low because I don''t think it''s that corporate a skyline.  Hope you don''t think I''m being too picky here Good luck</td>', 'This is a great picture; it''s dramatic, romantic and not unlike a postcard.  But, I''m going to score quite low because I don''t think it''s that corporate a skyline.  Hope you don''t think I''m being too picky here Good luck', '2002-07-30 10:45:00.000000', NULL, 1),
(97826, 3942, 2798, '<td valign="top">The subject being so central is a little too conventional and there''s an awful lot of sky in this skyline. The concept for the photo is fine, though. I think just perhaps turn the camera a little down and to the left. Perhaps catch some of that interesting lighting on that building in the bottom left. There is also evidence of sharpening around the edge of the building. This shows up as a slightly light line around the building edge.</td>', 'The subject being so central is a little too conventional and there''s an awful lot of sky in this skyline. The concept for the photo is fine, though. I think just perhaps turn the camera a little down and to the left. Perhaps catch some of that interesting lighting on that building in the bottom left. There is also evidence of sharpening around the edge of the building. This shows up as a slightly light line around the building edge.', '2002-07-30 11:07:00.000000', NULL, 1),
(97827, 3942, 1280, '<td valign="top">It shows me there house, but tells me nothing more about "Corporate World."   Nevertheless it is a certain appealing with it''s strong graphical lines.  My favorite part being the water tower in the distance....I''d like to see the sky have a little more character to add to the scenario.</td>', 'It shows me there house, but tells me nothing more about "Corporate World."   Nevertheless it is a certain appealing with it''s strong graphical lines.  My favorite part being the water tower in the distance....I''d like to see the sky have a little more character to add to the scenario.', '2002-07-31 21:49:00.000000', NULL, 1),
(97828, 3942, 737, '<td valign="top">Composition - ok<br/>Technical Aspects - good<br/>Meets Challenge - yes<br/>Visual Impact / Originality - ok<br/></td>', 'Composition - okTechnical Aspects - goodMeets Challenge - yesVisual Impact / Originality - ok', '2002-08-04 23:32:00.000000', NULL, 1),
(97829, 3944, 1054, '<td valign="top">Heheheh.  It took me a minute to figure this out.  Very funny. -ClubJuggle</td>', 'Heheheh.  It took me a minute to figure this out.  Very funny. -ClubJuggle', '2002-07-29 02:10:00.000000', NULL, 1),
(97830, 3944, 1792, '<td valign="top">Good composition, but perhaps sharper focus on some of the coins  would make it more interesting.</td>', 'Good composition, but perhaps sharper focus on some of the coins  would make it more interesting.', '2002-07-29 02:15:00.000000', NULL, 1),
